INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(49474, 'zhCN', '诅咒碎片', '前往位于破碎群岛的达拉然，将诅咒碎片交给奥法工匠维迪尔。', '<一块异样的金属碎片吸引了你的目光，你发现它正在变换着色彩。当你触碰到它时，碎片的一头突然膨胀，然后又熔化了。金属液滴落在地上，发出滋滋声。跟着，一股有毒的臭气侵袭了你的鼻腔。$b$b达拉然的某位金属工匠或许能告诉你它的情况。>', '', '', '', '', '', '', 25549),
(49473, 'zhCN', '泰坦级研究', '将$1oa个觉醒精华带给奥法工匠维迪尔。', '这种反应的剧烈程度正在与日俱增。我们虽然战胜了燃烧军团，但或许反而输掉了一些对我们极为重要的东西。\n\n这会是某种大规模剧变的征兆吗？我们的世界到底会变成什么样，$n？\n\n我会向我的熔炉寻求答案，我一辈子都在做这件事。而你的答案，我怀疑还在其他地方。', '', '', '', '', '', '', 25549),
(49472, 'zhCN', '泰坦级研究', '将$1oa个觉醒精华带给奥法工匠维迪尔。', '伊利丹或许是推动了命运之手，但将阿古斯拉到距离艾泽拉斯这么近的地方，加速了暗夜井的坍塌触发的某种反应。\n\n我认为军团在阿古斯的行动让我们从未知来源汲取多年的那种力量更加不稳定了。\n\n显然我们还需要进一步研究。', '', '', '', '', '', '', 25549),
(49445, 'zhCN', '源生贸易', '', '', '', '', '', '', '', '', 25549),
(49293, 'zhCN', '突击入侵', '完成3个普通侵入点。', '我们不能把任何一个世界让给军团。继续攻击侵入点，将军团碾碎。', '', '', '', '', '', '', 25549),
(49224, 'zhCN', '虚空之光熔炉', '使用虚空之光熔炉给一个圣物灌注坚韧虚空之光。', '熔炉发出了能量充沛的鸣响。很快我们的武器就可以像群星一样闪亮！\n\n如果要击败燃烧军团，我们就得获取那份力量。\n\n$n，你承受了许多苦难才带领我们走到现在。优先吸取熔炉力量的荣耀应该属于你。', '', '', '', '', '', '', 25549),
(49196, 'zhCN', '大型侵入点：深渊领主维尔姆斯', '', '', '', '', '', '', '', '', 25549),
(49195, 'zhCN', '大型侵入点：奥库拉鲁斯', '', '', '', '', '', '', '', '', 25549),
(49143, 'zhCN', '圣光之母的精华', '收集$1oa份圣光残迹。', '这是个关键时刻，$n。不能让这件事影响我们的士气。\n\n虽然泽拉已经逝去，但我依然能感觉到，她的精华就在我们身边。她心中闪耀的圣光依然能成为我们力量的源泉，为我们的事业提供帮助。\n\n毫无疑问，泽拉的死在图拉扬心中留下了一道伤疤。我会尽自己所能，安慰他痛苦的心。同时，请你去收集一下这位纳鲁遗留下来的残迹。', '', '', '', '', '', '', 25549),
(49135, 'zhCN', '阿古斯之心', '从安托鲁斯，燃烧王座的阿格拉玛身上收集4枚黑暗泰坦印记（史诗难度）。', '哈顿告诉我，阿古斯陷落后，萨格拉斯就下令在星球的核心深处建造了一座黑暗神殿。我们对这座神殿知之甚少，因为只有黑暗泰坦最忠实的亲信才能获得进入那里的印记。\n\n如果我们能得到印记，就可以把它们灌注进维迪卡尔。这样我们的部队就可以直接进攻阿古斯的腐化之心了。', '', '', '', '', '', '', 25549),
(49134, 'zhCN', '阿古斯之心', '从安托鲁斯，燃烧王座的阿格拉玛身上收集4枚黑暗泰坦印记（英雄难度）。', '哈顿告诉我，阿古斯陷落后，萨格拉斯就下令在星球的核心深处建造了一座黑暗神殿。我们对这座神殿知之甚少，因为只有黑暗泰坦最忠实的亲信才能获得进入那里的印记。\n\n如果我们能得到印记，就可以把它们灌注进维迪卡尔。这样我们的部队就可以直接进攻阿古斯的腐化之心了。', '', '', '', '', '', '', 25549),
(49133, 'zhCN', '阿古斯之心', '从安托鲁斯，燃烧王座的阿格拉玛身上收集4枚黑暗泰坦印记（普通难度）。', '哈顿告诉我，阿古斯陷落后，萨格拉斯就下令在星球的核心深处建造了一座黑暗神殿。我们对这座神殿知之甚少，因为只有黑暗泰坦最忠实的亲信才能获得进入那里的印记。\n\n如果我们能得到印记，就可以把它们灌注进维迪卡尔。这样我们的部队就可以直接进攻阿古斯的腐化之心了。', '', '', '', '', '', '', 25549),
(49099, 'zhCN', '侵入点：博尼克', '', '', '', '', '', '', '', '', 25549),
(49098, 'zhCN', '侵入点：森加', '', '', '', '', '', '', '', '', 25549),
(49097, 'zhCN', '侵入点：萨古亚', '', '', '', '', '', '', '', '', 25549),
(49096, 'zhCN', '侵入点：奈格塔尔', '', '', '', '', '', '', '', '', 25549),
(49091, 'zhCN', '侵入点：瓦尔', '', '', '', '', '', '', '', '', 25549),
(49077, 'zhCN', '反思之时', '带着伊利丹的水晶去找他最亲近的人和最熟悉的地方。', '<这块水晶召唤着你，它正在与巫术魔法共鸣。\n\n当你握住它时，听到了里面留下的信息，那是伊利丹交给你的任务。>', '', '', '', '', '', '', 25549),
(49076, 'zhCN', '黑暗通道', '从安托鲁斯，燃烧王座的猎魂者伊墨纳尔身上收集4枚通行符文（史诗难度）。', '尽管阿古斯的核心散发着危险的能量，猎魂者却可以在燃烧王座随意走动。我们的斥候报告说他的舰船拥有恶魔符文的力量，可以抵达安全抵达邪能圣堂。\n\n如果我们能得到这些符文，维迪卡尔就可以使用这条航线。这可以为我们的部队节省宝贵的时间。', '', '', '', '', '', '', 25549),
(49075, 'zhCN', '黑暗通道', '从安托鲁斯，燃烧王座的猎魂者伊墨纳尔身上收集4枚通行符文（英雄难度）。', '尽管阿古斯的核心散发着危险的能量，猎魂者却可以在燃烧王座随意走动。我们的斥候报告说他的舰船拥有恶魔符文的力量，可以抵达安全抵达邪能圣堂。\n\n如果我们能得到这些符文，维迪卡尔就可以使用这条航线。这可以为我们的部队节省宝贵的时间。', '', '', '', '', '', '', 25549),
(49057, 'zhCN', '小型克西斯号', '', '', '', '', '', '', '', '', 25549),
(49051, 'zhCN', '阿古斯的腐化之血', '', '', '', '', '', '', '', '', 25549),
(49048, 'zhCN', '鼠鼠', '', '', '', '', '', '', '', '', 25549),
(49042, 'zhCN', '污染之爪', '', '', '', '', '', '', '', '', 25549),
(49032, 'zhCN', '黑暗通道', '从安托鲁斯，燃烧王座的猎魂者伊墨纳尔身上收集4枚通行符文（普通难度）。', '尽管阿古斯的核心散发着危险的能量，猎魂者却可以在燃烧王座随意走动。我们的斥候报告说他的舰船拥有恶魔符文的力量，可以抵达安全抵达邪能圣堂。\n\n如果我们能得到这些符文，维迪卡尔就可以使用这条航线。这可以为我们的部队节省宝贵的时间。', '', '', '', '', '', '', 25549),
(49015, 'zhCN', '泰坦陨落', '击败安托鲁斯，燃烧王座的阿古斯之魂。', '语言无法表达我的痛苦，我的愤怒。萨格拉斯的所作所为……$b$b阿古斯，我的家园，拥有泰坦之魂。它已经被扭曲，被腐化，完全无法救赎。它的力量被奴役，作为燃烧军团无尽大军的燃料。$b$b我们必须完成这个不可能完成的任务……突破安托鲁斯的深渊，切断燃烧军团与世界之魂的联系。$b$b求求你，$n，终结它的痛苦。消灭阿古斯的黑暗之心后，我们就可以击败燃烧军团……并为我的世界的灵魂带去救赎。', '', '', '', '', '', '', 25549),
(49014, 'zhCN', '燃烧王座', '在安托兰废土上方与大技师罗姆尔谈一谈，打开通向安托鲁斯的道路。', '时机成熟了，$n，可以开始攻打安托鲁斯了。我们多年的奋斗，以及亲友所作出的牺牲，终于让我们走到了今天。$b$b我们会用圣光裁决者轰开这座诅咒堡垒的高墙，踏平他们的权力中心。我们会成为燃烧军团的终结者。$b$b你在这场战争中居功至伟，这份荣耀应该属于你。跟罗姆尔谈一谈，让我们一起完成这份使命。', '', '', '', '', '', '', 25549),
(49007, 'zhCN', '指挥官登场！', '使用维沙克斯的传送门。', '<设备开始轰鸣，你可以进入中队指挥官维沙克斯在安托兰废土的传送门了。>', '', '', '', '', '', '', 25549),
(48983, 'zhCN', '规范采掘', '', '', '', '', '', '', '', '', 25549),
(48982, 'zhCN', '侵入点：奥雷诺', '', '', '', '', '', '', '', '', 25549),
(48977, 'zhCN', '圣光军团的物资', '与维迪卡尔的守备官嘉兰娜谈一谈，领取你的奖励。', 'Archenon poros，勇士。\n\n圣光军团希望感谢你帮忙对抗燃烧军团在阿古斯的部队。\n\n这些物资代表着我们的谢意，请收下吧。在你的不懈努力下，我们距离终极目标铲除军团又近了一步。', '', '', '', '', '', '', 25549),
(48976, 'zhCN', '阿古斯防卫军的物资', '与维迪卡尔的可敬的托兰谈一谈。', '$ct，多亏了你的努力，我们的军队从战场上成功找到了这些资源，没让它们落入燃烧军团的手中。\n\n只要你继续帮助我们，我们就可以提供额外的资源。', '', '', '', '', '', '', 25549),
(48974, 'zhCN', '圣光军团的典范', '与维迪卡尔的守备官嘉兰娜谈一谈。', '你在圣光军团的盟友想感谢你长久以来对他们的帮助。他们正在维迪卡尔上等你。', '', '', '', '', '', '', 25549),
(48973, 'zhCN', '阿古斯防卫军的典范', '与维迪卡尔的可敬的托兰谈一谈。', '你在阿古斯防卫军的盟友请求你前去他们那里。他们想酬谢你对他们长久以来的帮助。', '', '', '', '', '', '', 25549),
(48958, 'zhCN', '打断仪式', '', '', '', '', '', '', '', '', 25549),
(48954, 'zhCN', '泰坦之血', '把寂灭者阿古斯的血交给达拉然的卡德加。', '<就在你眼皮底下，一滴血从死去的泰坦阿古斯身上流了下来，凝结成了一颗完美无瑕的宝石。你把它握在掌心，感觉到里面散发出深不可测的力量……以及久久不息的痛苦和悲伤。\n\n这是这场本来毫无胜算的战斗的最后残留，是根本不可能完成的成就。而且，就跟所有胜利一样，它也伴随着惨痛的代价。\n\n你立刻意识到应该把这份战利品交给谁。>', '', '', '', '', '', '', 25549),
(48953, 'zhCN', '执政团之座：黑暗召唤者', '', '', '', '', '', '', '', '', 25549),
(48952, 'zhCN', '有来无回', '', '', '', '', '', '', '', '', 25549),
(48951, 'zhCN', '执政团之座：虚空之喉', '', '', '', '', '', '', '', '', 25549),
(48937, 'zhCN', '制造虚无行者的传送门发生器', '', '', '', '', '', '', '', '', 25549),
(48931, 'zhCN', '巨兽觉醒', '', '', '', '', '', '', '', '', 25549),
(48929, 'zhCN', '估量对手', '与图拉扬谈一谈。', '如果你的大主教得知我们没有足够的资源来突袭安托鲁斯的话，一定会很焦躁的。他引以为傲的圣光军团居然会战力不足，这对他来说恐怕很难接受。\n\n但他的自尊心与我无关。在他策划下一步行动的同时，我会用恶魔的鲜血来洗刷这片土地。\n\n去吧。要获得最终的胜利，我们还有很多事情要做。', '', '', '', '', '', '', 25549),
(48912, 'zhCN', '支援安托兰战役', '完成10个侵入点。', '军团需要从他们征服的世界中收集原料，为远征提供物资。穿过军团传送门，消灭你遇到的恶魔，不让他们获取维持战争机器所需的资源。', '', '', '', '', '', '', 25549),
(48911, 'zhCN', '虚空接种', '收集100块浓缩的虚空碎片。', '所有被暗影触摸过的东西都会在被击败后留下虚空的痕迹，如果你能在城市中收集到足够的虚空物质，就回来找我。我可以把它们提纯。 \n\n我们可以拯救更多族人。', '', '', '', '', '', '', 25549),
(48910, 'zhCN', '补给克罗库恩', '收集$1oa点职业大厅资源。', '这个地方过于贫瘠，几乎没有什么产出。我的人民时刻都在温饱线上挣扎。如果我有更多补给，就可以再给你一个山岭猎手。\n\n外乡人，你意下如何？', '', '', '', '', '', '', 25549),
(48875, 'zhCN', '恶魔鸡尾酒', '', '', '', '', '', '', '', '', 25549),
(48867, 'zhCN', '首席炼金师蒙库鲁斯', '', '', '', '', '', '', '', '', 25549),
(48864, 'zhCN', '破碎者铁匠', '找到铁匠盖尔。', '$C，这可能是执政团军械库的钥匙碎片。我们在逃离阿古斯时把它锁上了。我最后一次见到这把钥匙时，我的副官阿塔拉还带领着一支部队守护军械库呢。那都是好久之前了……\n\n我虽然不确定，但还有一个人或许也知道这件事。铸造这把钥匙的工匠叫做盖尔。听说克罗库恩还有幸存的破碎者，说不定他也在其中。', '', '', '', '', '', '', 25549),
(48836, 'zhCN', '监视者艾瓦', '', '', '', '', '', '', '', '', 25549),
(48835, 'zhCN', '驯犬大师克拉克斯', '', '', '', '', '', '', '', '', 25549),
(48834, 'zhCN', '裂世者斯库尔', '', '', '', '', '', '', '', '', 25549),
(48833, 'zhCN', '仪式完成', '', '', '', '', '', '', '', '', 25549),
(48831, 'zhCN', '指挥官泰克拉兹', '', '', '', '', '', '', '', '', 25549),
(48830, 'zhCN', '审判官维斯洛兹', '', '', '', '', '', '', '', '', 25549),
(48829, 'zhCN', '愤怒领主亚雷兹', '', '', '', '', '', '', '', '', 25549),
(48828, 'zhCN', '萨卡尔中尉', '', '', '', '', '', '', '', '', 25549),
(48827, 'zhCN', '瓦加', '', '', '', '', '', '', '', '', 25549),
(48803, 'zhCN', '铸造通往过去的钥匙', '旁观盖尔重铸军械库钥匙。', '军械库的钥匙碎片已经集齐，枝蔓晶簇也可以提供足够的能量来重铸钥匙。$b$b这应该不会花多久的时间……应该会成功的。我已经很久没有做过这种东西了！', '', '', '', '', '', '', 25549),
(48799, 'zhCN', '废墟世界的燃料', '从阿古斯的侵入点、稀有怪物或宝藏处收集$1oa颗太古阿古尼特水晶。', '这片废土上有一种珍贵的资源，$n。$b$b阿古尼特水晶曾经在阿古斯随处可见。它的神奇特性帮助艾瑞达文明走向了繁荣。比起留给军团，还是让我们自己来好好使用这些水晶吧。$b$b请尽力寻找太古阿古尼特水晶，勇士。你找到的每一颗水晶都会对我们的事业有所帮助。', '', '', '', '', '', '', 25549),
(48783, 'zhCN', '无人期待', '', '', '', '', '', '', '', '', 25549),
(48780, 'zhCN', '利剑', '', '', '', '', '', '', '', '', 25549),
(48777, 'zhCN', '恶魔巢穴', '', '', '', '', '', '', '', '', 25549),
(48738, 'zhCN', '万千之主祖尔坦', '', '', '', '', '', '', '', '', 25549),
(48735, 'zhCN', '监视者伊索纳', '', '', '', '', '', '', '', '', 25549),
(48734, 'zhCN', '监视者伊比达', '', '', '', '', '', '', '', '', 25549),
(48733, 'zhCN', '杰德尼勇士沃鲁斯克', '', '', '', '', '', '', '', '', 25549),
(48729, 'zhCN', '阿塔克松', '', '', '', '', '', '', '', '', 25549),
(48727, 'zhCN', '法鲁克队长', '', '', '', '', '', '', '', '', 25549),
(48725, 'zhCN', '毒尾天鳍鳐', '', '', '', '', '', '', '', '', 25549),
(48701, 'zhCN', '嗜血的巴鲁特', '', '', '', '', '', '', '', '', 25549),
(48691, 'zhCN', '灵魂之链', '', '', '', '', '', '', '', '', 25549),
(48688, 'zhCN', 'Lockout Tracking - Boss - Islands', '', '', '', '', '', '', '', '', 25549),
(48686, 'zhCN', 'Lockout Tracking - Boss - Ice', '', '', '', '', '', '', '', '', 25549),
(48668, 'zhCN', '光铸道标：城市中心', '激活维迪卡尔道标。', '你好，朋友！$b$b法瑞娅队长派我们先行清理这片地区。我们刚准备放置道标，并向维迪卡尔汇报。$b$b如果你能帮助我们完成任务，我们将不胜荣幸。$b$b信号道标只需要轻轻一点就可以了。大技师会接手余下的工作。', '', '', '', '', '', '', 25549),
(48662, 'zhCN', '超短引线', '', '', '', '', '', '', '', '', 25549),
(48654, 'zhCN', '奥罗纳尔之下', '与奥罗纳尔下方的克罗库谈一谈。', '我们在奥罗纳尔下方找到的克罗库不愿意离开。$n，你能和他谈谈吗？说服他登上维迪卡尔。', '', '', '', '', '', '', 25549),
(48642, 'zhCN', '阿古斯防卫军', '在阿古斯完成任意4个阿古斯防卫军世界任务。', '完成4个世界任务，协助阿古斯防卫军。', '', '', '', '', '', '向维迪卡尔的可敬的托兰复命。', 25549),
(48641, 'zhCN', '抗魔联军', '在破碎海滩完成任意4个世界任务。', '完成4个世界任务，协助抗魔联军。', '', '', '', '', '', '返回破碎海滩，去找指挥官钱伯斯。', 25549),
(48640, 'zhCN', '不朽者中队', '', '', '', '', '', '', '', '', 25549),
(48639, 'zhCN', '圣光军团', '在阿古斯完成4个圣光军团世界任务。', '完成4个世界任务，协助圣光军团。', '', '', '', '', '', '返回阿古斯的维迪卡尔，与守备官嘉兰娜谈一谈。', 25549),
(48637, 'zhCN', '净化之火', '', '', '', '', '', '', '', '', 25549),
(48636, 'zhCN', '扶助安托兰战役', '完成10个侵入点。', '军团需要从他们征服的世界中收集原料，为远征提供物资。穿过军团传送门，消灭你遇到的恶魔，不让他们获取维持战争机器所需的资源。', '', '', '', '', '', '', 25549),
(48635, 'zhCN', '更多虚空接种', '收集100块浓缩的虚空碎片。', '所有被暗影触摸过的东西都会在被击败后留下虚空的痕迹，如果你能在城市中收集到足够的虚空物质，就回来找我。我可以把它们提纯。 \n\n我们可以拯救更多族人。', '', '', '', '', '', '', 25549),
(48634, 'zhCN', '深入补给克罗库恩', '收集$1oa点职业大厅资源。', '这个地方过于贫瘠，几乎没有什么产出。我的人民时刻都在温饱线上挣扎。如果我有更多补给，就可以再给你一个山岭猎手。\n\n外乡人，你意下如何？', '', '', '', '', '', '', 25549),
(48605, 'zhCN', '指挥官之陨', '完成一个大型侵入点场景战役。', '燃烧军团的勇士在侵入点里会变得不堪一击！把它找出来干掉，别让它回到阿古斯战斗。', '', '', '', '', '', '', 25549),
(48601, 'zhCN', '粉碎邪火', '使用侦察地图并完成任务“突袭邪火军械库”。', '恶魔小径上有几座单薄的石桥，连接起燃烧裂口与邪火军械库。你的部队进攻军械库本体的时候，圣光军团会阻挡住军团的援军。\n\n动作一定要快。', '', '', '', '', '', '', 25549),
(48600, 'zhCN', '挫其锐气', '将6名勇士的装备等级提升到950。', '从安托鲁斯涌出的恶魔都在邪火军械库领取装备。我们必须摧毁那些武器。你的$cs是否会再次与圣光军团并肩作战？\n\n在发动攻击前，先收集材料。我的铁匠会为你的士兵制造更为强大的护甲。军团不可能束手就擒，乖乖交出邪火军械库。', '', '', '', '', '', '', 25549),
(48592, 'zhCN', '守卫塔楼', '', '', '', '', '', '', '', '', 25549),
(48560, 'zhCN', '暗影的礼物', '将暗影精华灌注进虚空之光熔炉。', '你感觉到了吗，$n？这精华中的黑暗之力非常明显。\n\n如果是在过去，我可能会对这种力量退避三舍，甚至否定它的存在。但如果说我们在漫长的斗争中学到了什么的话，那就是光与影必须共存。\n\n这可能就是我们需要的东西，有了它，虚空之光熔炉就能获得平衡。我们就能在对抗军团的战斗中获得优势。\n\n把这份精华灌注进熔炉吧，勇士。这样一来，距离发掘你武器的全部潜能就又近了一步。', '', '', '', '', '', '', 25549),
(48559, 'zhCN', '圣光的礼物', '将圣光精华融入虚空之光熔炉。', '我感觉到了，这就是泽拉的崇高心灵。她对燃烧军团坚持不懈的抵抗。就让这成为她留给人们的财富吧。\n\n建造维迪卡尔时，我们修筑了虚空之光熔炉，以驾驭弥漫在阿古斯强大的能量。我相信泽拉的精华是我们达到这一目标的关键之一。\n\n但是光有圣光还不够。没有平衡，就没有和谐，也没有力量的聚集。\n\n把这个精华放进熔炉吧，勇士。要想获得终结燃烧的远征的力量，这是第一步。', '', '', '', '', '', '', 25549),
(48544, 'zhCN', '哇，真快！', '向克罗库营地的酋长哈顿复命。', '$n，非常感谢。接下来就交给我的驯兽师吧。不知你是否还能帮我一个小忙，给酋长哈顿带条口信？告诉他森林再次安全了。我相信他肯定会感谢你的辛勤付出。\n\n我会把我们最快的岩羊借给你赶路。穿过森林外的小路时记得两边看看，那边有巨大的军团歼灭者在巡逻。祝你好运！', '', '', '', '', '', '', 25549),
(48542, 'zhCN', '反击', '在石化森林击杀$1oa名艾瑞达仪祭师和莎拉扎德夫人。', '这张卷轴详细记述了一个黑暗法术，可以窃取附近克罗库的灵魂，用以制造新的恶魔：乌祖尔。卷轴上有莎拉扎德夫人的签名。', '', '', '', '', '', '', 25549),
(48526, 'zhCN', '搞点破坏', '', '', '', '', '', '', '', '', 25549),
(48514, 'zhCN', '沉眠的巨兽', '', '', '', '', '', '', '', '', 25549),
(48513, 'zhCN', '攻击侵入点', '完成3个侵入点。', '侵入点是切断燃烧军团往阿古斯运送援军的关键。击败次级传送门里的军团部队能够让我们袭击更加大型的侵入点，并消灭那里的军团部队。', '', '', '', '', '', '', 25549),
(48512, 'zhCN', '苏薇西娅姐妹', '', '', '', '', '', '', '', '', 25549),
(48510, 'zhCN', '指挥官维卡娅', '', '', '', '', '', '', '', '', 25549),
(48509, 'zhCN', '指挥官萨森纳尔', '', '', '', '', '', '', '', '', 25549),
(48507, 'zhCN', '命运之手', '在刃拳海湾与前往埃索达的护送者见面。', '自从燃烧军团入侵埃索达以来，德莱尼人一直在努力，时刻准备返回阿古斯。终于，他们打造出了一艘能够带我们前往那里的飞船。\n\n通往那个可怕世界的通道已经打开，这是我们最好的反攻机会。先知维伦特别要求你加入突击队。\n\n你最好立刻赶去刃拳海湾。我们已经安排好船只带你前往秘蓝岛。', '', '', '', '', '', '', 25549),
(48506, 'zhCN', '命运之手', '在暴风城港口与前往埃索达的护送者见面。', '自从燃烧军团入侵埃索达以来，德莱尼人一直在努力，时刻准备返回阿古斯。终于，他们打造出了一艘能够带我们前往那里的飞船。\n\n通往那个可怕世界的通道已经打开，这是我们最好的反攻机会。先知维伦特别要求你加入突击队。\n\n你最好立刻赶去暴风城港口。我们已经安排好船只带你前往秘蓝岛。', '', '', '', '', '', '', 25549),
(48502, 'zhCN', '纳罗瓦，森林之王', '', '', '', '', '', '', '', '', 25549),
(48500, 'zhCN', '片刻喘息', '与维迪卡尔上的技师席拉娜、塞布斯·锥点和高阶女祭司伊莎娜对话。', '我们经历了这么多，必须谨记，绝不能沉湎于过去，而是要向前看，为未来做好准备。\n\n你也趁此机会熟悉一下维迪卡尔。', '', '', '', '', '', '', 25549),
(48483, 'zhCN', '陌生人的请求', '治疗$1oa名邪缚苦工。', '我的人民……被奴役……\n\n被折磨……命悬一线……\n\n<戴着兜帽的人虚弱地抬起双臂,向你递来一份药膏。>\n\n帮帮……我们……', '', '', '', '', '', '与毁灭之冠的先知维伦见面。', 25549),
(48466, 'zhCN', '维农', '', '', '', '', '', '', '', '', 25549),
(48465, 'zhCN', '弗拉克苏尔', '', '', '', '', '', '', '', '', 25549),
(48461, 'zhCN', '出其不意', '进入一个侵入点，击败一个军团指挥官。', '军团的狂热远征导致他们兵力分散。趁着他们将重心放在阿古斯的防御上，我们可以前往其他世界削弱他们的兵力。\n\n穿过阿古斯上的一个侵入点，让军团知道他们已经在劫难逃。', '', '', '', '', '', '', 25549),
(48460, 'zhCN', '骑兵', '与石化森林的首席骑兵贾伊德对话。', '阿古斯有许多邪恶的存在，而我们的森林里就住着其中最可怕的几个。我的骑兵们正在森林边缘等待增援。也就是在等你。\n\n找到首席骑兵贾伊德，他会详细说明。', '', '', '', '', '', '', 25549),
(48455, 'zhCN', '暮影豹问题', '在石化森林里击杀$1oa头影豹。', '这座森林里依然游荡着塔布羊和影豹。但平衡已被打破，如今影豹几乎要将塔布羊捕食殆尽。为保障它们的存活，我们必须削减影豹的数量。\n\n不要让它们痛苦太久。干脆的死亡就是最大的仁慈。', '', '', '', '', '', '', 25549),
(48453, 'zhCN', '反击', '在石化森林杀死$1oa名艾瑞达仪祭师和莎拉扎德夫人。', '你可能已经看到了，这座森林里的仪祭师绑架了我们的人民，并用他们施展可怕的仪式。死者们的灵魂如今化为扭曲的怪物，四处徘徊。他们的罪恶必须得到严惩。尽可能多杀几个仪祭师，但一定要击杀领导他们的黑暗恶魔。', '', '', '', '', '', '', 25549),
(48448, 'zhCN', '阻截军团的战争机器', '使用侦察地图并完成任务“废土行动”。', '$ct，我需要你的帮助。圣光军团正在策划一场针对炼魂熔炉、终端船坞和塑造者高台的袭击，以削弱军团在安托兰废土以外发动战争的能力。但我们的士兵数量不足以在守卫据点的同时执行这项计划。\n\n你是否可以代表我们去联系$cs？如果他们与我们并肩作战，这个计划就能够成功。我们也就能令燃烧军团的战争机器瘫痪。', '', '', '', '', '', '', 25549),
(48447, 'zhCN', '驱赶影卫', '使用侦察地图并完成任务“驱赶影卫”。', '希望你们的组织再次助我一臂之力，这样我们也许有机会彻底终结影卫的威胁。当你们迎战军团时，我们将与虚空对抗。等你的部队抵达后就开始进攻。', '', '', '', '', '', '', 25549),
(48446, 'zhCN', '古代艾瑞达圣物', '将6名勇士的装备等级提升到925。', '我曾令阿坎恩失望。我不会再重蹈覆辙。 \n\n只要将虚灵赶出玛凯雷，就有希望解放克罗库。鲁拉已被击败，但虚空依然在影卫入侵营地附近弥漫。\n\n我们出发之前，请确保你的部队不会受到暗影的伤害。你的勇士最好去附近的废墟里寻找一些远古艾瑞达军械。', '', '', '', '', '', '', 25549),
(48445, 'zhCN', '奥罗纳尔废墟', '使用侦察地图并完成任务“疯狂边缘”。', '许多克罗库在下方城市中徘徊，浑身笼罩着暗影。但我相信他们还有救。\n\n阿坎恩曾经是一位领袖。他的一些追随者可能仍然居住在奥罗纳尔的废墟里，在理智和湮灭的边缘挣扎。请你的组织伸出援手，在废墟中搜寻还有救的人。', '', '', '', '', '', '', 25549),
(48443, 'zhCN', '纳斯拉克斯要塞：救援任务', '使用侦察地图并完成任务“纳斯拉克斯越狱”。', '你的部队已经做好了充分准备，足以从纳斯拉克斯手中解救我的人民。派遣你的勇士支援我的突袭，我们将联手打破军团对这片地区的控制。', '', '', '', '', '', '', 25549),
(48442, 'zhCN', '纳斯拉克斯要塞：准备', '将6名勇士的装备等级提升到900。', '被带往纳斯拉克斯要塞的克罗库囚犯只有两种命运：接受邪能，自愿成为无穷无尽的燃烧军团的一员；或者变异，成为丑陋的怪物——乌祖尔。\n\n趁着圣光军团吸引了燃烧军团的注意力，我现在有机会拯救我的人民。希望你能帮助我。\n\n在我们出发之前，你的部队必须做好充分准备。', '', '', '', '', '', '', 25549),
(48441, 'zhCN', '堕暗岭遗留物资', '使用侦察地图并完成任务“堕暗岭物资”。', '我的骑士们有塔布羊，但我的人民需要物资，比如食品、工具和武器。\n\n数千年来，我们不断在一座座简陋的小屋之间辗转，每次被军团发现都要搬迁。我们无法带着财物逃跑，所以只能将它们留在原地。\n\n你很强大，你的追随者也能力非凡，但你并不了解阿古斯。这里的环境会像军团一样无情地杀死你。去堕暗岭找回我们的物资，我会派我的人来指引你的部队穿越阿古斯废土。', '', '', '', '', '', '', 25549),
(48440, 'zhCN', '步入夜色', '登上维迪卡尔，前往阿古斯。', '我们今天所做的一切，都是为了艾泽拉斯。为了死在燃烧军团邪恶远征之下的无数亡魂。\n\n等你准备好以后，我们会将维迪卡尔开进军团的最核心。\n\n阿古斯等待着你。', '', '', '', '', '', '与阿古斯的维迪卡尔上的先知维伦谈一谈。', 25549),
(48386, 'zhCN', '杰德尼大赛', '', '', '', '', '', '', '', '', 25549),
(48376, 'zhCN', '大量源生抑魔金', '', '', '', '', '', '', '', '', 25549),
(48375, 'zhCN', '源生抑魔金', '', '', '', '', '', '', '', '', 25549),
(48374, 'zhCN', '补给需求：光纹布', '', '', '', '', '', '', '', '', 25549),
(48373, 'zhCN', '产品订单：光纹布', '', '', '', '', '', '', '', '', 25549),
(48364, 'zhCN', '产品订单：海丝利安石', '', '', '', '', '', '', '', '', 25549),
(48363, 'zhCN', '产品订单：炫彩孔雀石', '', '', '', '', '', '', '', '', 25549),
(48360, 'zhCN', '补给需求：恶魔皮革', '', '', '', '', '', '', '', '', 25549),
(48359, 'zhCN', '产品订单：恶魔皮革', '', '', '', '', '', '', '', '', 25549),
(48358, 'zhCN', '补给需求：天界金', '', '', '', '', '', '', '', '', 25549),
(48349, 'zhCN', '产品订单：天界金', '', '', '', '', '', '', '', '', 25549),
(48345, 'zhCN', '塔尔加斯的部队', '杀死12名塔尔加斯的部队成员。', '我必须继续寻找知识桂冠，我的朋友。只有完整的执政团之冠才能扭转我们所面临的战争颓势。$b$b塔尔加斯的部队是我们实现目标的阻碍。我需要你去清出一条道路。$b$b我们绝不允许任何人挡在面前。即使是塔尔加斯也不行。', '', '', '', '', '', '', 25549),
(48344, 'zhCN', '出问题了', '在奥秘学宫与图拉扬见面。', '我们遇到一个麻烦，$n。燃烧军团已经来到玛凯雷。$b$b当你拿到启迪印记的时候，就等于向整个阿古斯宣告我们的存在。安托鲁斯的视线已经聚焦到我们身上。$b$b等等。还有更糟的。$b$b维伦带着法瑞娅队长和她的部队进入阿尔诺花园，去寻找知识桂冠。据我所知，他们现在都被困在敌人的兵线后方。$b$b和我一起去奥秘学宫。我们必须把维伦和其他人带回来，否则就迟了。', '', '', '', '', '', '', 25549),
(48338, 'zhCN', '补给需求：星辰之耀', '', '', '', '', '', '', '', '', 25549),
(48337, 'zhCN', '产品订单：星辰之耀', '', '', '', '', '', '', '', '', 25549),
(48323, 'zhCN', '产品订单：纳鲁之泪', '', '', '', '', '', '', '', '', 25549),
(48318, 'zhCN', '产品订单：光血药剂', '', '', '', '', '', '', '', '', 25549),
(48305, 'zhCN', '燃烧的女巫会', '击败安托鲁斯，燃烧王座的破坏魔女巫会。', '即使是泰坦也无法忍受他们的折磨。把破坏魔女巫会干掉吧。', '', '', '', '', '', '', 25549),
(48304, 'zhCN', '猎魂者', '击败安托鲁斯，燃烧王座的猎魂者伊墨纳尔。', '伊墨纳尔是扭曲虚空中有史以来最致命的赏金猎人。找个地方把他解决掉。', '', '', '', '', '', '', 25549),
(48303, 'zhCN', '安托兰统帅议会', '击败安托鲁斯，燃烧王座的安托兰统帅议会。', '燃烧军团花费了一万多年的时间策划对艾泽拉斯的入侵。击败他们的首领，让他们再也无法威胁到我们的世界。', '', '', '', '', '', '', 25549),
(48301, 'zhCN', '燃烧的女巫会', '击败安托鲁斯，燃烧王座的破坏魔女巫会。', '即使是泰坦也无法忍受他们的折磨。把破坏魔女巫会干掉吧。', '', '', '', '', '', '', 25549),
(48300, 'zhCN', '猎魂者', '击败安托鲁斯，燃烧王座的猎魂者伊墨纳尔。', '伊墨纳尔是扭曲虚空中有史以来最致命的赏金猎人。找个地方把他解决掉。', '', '', '', '', '', '', 25549),
(48299, 'zhCN', '安托兰统帅议会', '击败安托鲁斯，燃烧王座的安托兰统帅议会。', '燃烧军团花费了一万多年的时间策划对艾泽拉斯的入侵。击败他们的首领，让他们再也无法威胁到我们的世界。', '', '', '', '', '', '', 25549),
(48297, 'zhCN', '燃烧的女巫会', '击败安托鲁斯，燃烧王座的破坏魔女巫会。', '即使是泰坦也无法忍受他们的折磨。把破坏魔女巫会干掉吧。', '', '', '', '', '', '', 25549),
(48296, 'zhCN', '猎魂者', '击败安托鲁斯，燃烧王座的猎魂者伊墨纳尔。', '伊墨纳尔是扭曲虚空中有史以来最致命的赏金猎人。找个地方把他解决掉。', '', '', '', '', '', '', 25549),
(48295, 'zhCN', '安托兰统帅议会', '击败安托鲁斯，燃烧王座的安托兰统帅议会。', '燃烧军团花费了一万多年的时间策划对艾泽拉斯的入侵。击败他们的首领，让他们再也无法威胁到我们的世界。', '', '', '', '', '', '', 25549),
(48293, 'zhCN', '燃烧的女巫会', '击败安托鲁斯，燃烧王座的破坏魔女巫会。', '即使是泰坦也无法忍受他们的折磨。把破坏魔女巫会干掉吧。', '', '', '', '', '', '', 25549),
(48292, 'zhCN', '猎魂者', '击败安托鲁斯，燃烧王座的猎魂者伊墨纳尔。', '伊墨纳尔是扭曲虚空中有史以来最致命的赏金猎人。找个地方把他解决掉。', '', '', '', '', '', '', 25549),
(48288, 'zhCN', '安托兰统帅议会', '击败安托鲁斯，燃烧王座的安托兰统帅议会。', '燃烧军团花费了一万多年的时间策划对艾泽拉斯的入侵。击败他们的首领，让他们再也无法威胁到我们的世界。', '', '', '', '', '', '', 25549),
(48284, 'zhCN', '战场死神', '', '', '', '', '', '', '', '', 25549),
(48280, 'zhCN', '另一位的幻象', '与麦格尼一起见证阿古斯的幻象。', '无论现在想要联系我们的人是谁，都有可能带来寻找艾欧娜尔所需的线索。\n\n我们必须立即去看看情况！', '', '', '', '', '', '', 25549),
(48277, 'zhCN', '代言人的寻找', '与克罗库营地的麦格尼见面。', '我们的部队已经做好战斗准备，但我们依然不知道艾欧娜尔的灵魂在哪里。\n\n你最好立即去见麦格尼，看看我们是否还有机会找到她。如果她已经堕落，那么我们召集再多人手也不可能对抗萨格拉斯。', '', '', '', '', '', '与克罗库营地的麦格尼见面。', 25549),
(48273, 'zhCN', '代言人的倾听', '与克罗库营地的麦格尼见面。', '麦格尼又要你去克罗库营地了。他在尝试联系阿古斯方面似乎取得了新进展。\n\n我建议你立即去见他。他的上一个幻象预言了阿格拉玛的到来，我们对于萨格拉斯的计划还所知甚少。', '', '', '', '', '', '与克罗库营地的麦格尼见面。', 25549),
(48272, 'zhCN', '恐惧幻象', '与麦格尼一起见证阿古斯的幻象。', '我做到了，$G小伙子:丫头;。我又联系上他了！ \n\n哦，但真的好痛苦。好痛苦！他的情况不妙，极其不妙！\n\n你必须和我一起倾听才能明白。', '', '', '', '', '', '', 25549),
(48271, 'zhCN', '找回碎片', '从执政团之座周围的虚灵身上找到丢失的钥匙碎片。', '你找到的只是一块钥匙碎片，恐怕其他碎片落在了你说的那些虚灵生物手上……就是那些“影卫虚灵”。\n\n我们必须把碎片全都找回来。执政团之座内外的影卫虚灵首领和副官手上很可能就有这些碎片。\n\n去把那些钥匙碎片找回来，$n……无论采取什么手段。', '', '', '', '', '', '', 25549),
(48261, 'zhCN', '重铸能量', '获得大量枝蔓晶簇。', '我是用太古阿古尼特水晶打造的这把钥匙。不幸的是，现在剩下的水晶都被用在圣光军团的防御工事上了。\n\n唔……枝蔓晶簇大概也能行。玛凯雷的精英经常用它们来给简易的设备供能。如果还可以找到完整的城市废墟，那么我猜那里的堕落法师或破碎者身上可能还带着一些。 \n\n当然，我们需要许多这种晶簇才能重铸钥匙。看来又到你出马的时候了。', '', '', '', '', '', '', 25549),
(48231, 'zhCN', '执政团护甲', '获得圣光护甲并将它交给档案员伊欧纳。', '这把重铸的钥匙可以打开执政团之座里面的军械库。\n\n锁在里面的是执政团护甲。这套护甲是在萨格拉斯毁灭我们的世界之前打造的。绝不能让虚空的势力偷走这套护甲。\n\n拿到护甲后，请交给档案员伊欧纳。他把我们最珍贵的圣物都存放在这条路尽头的洞窟里。他一定会很乐意接受这套护甲。', '', '', '', '', '', '', 25549),
(48230, 'zhCN', '过去的碎片', '将发光的钥匙碎片交给法瑞娅队长。', '<你的目光被一块散发着微弱光芒的水晶碎块所吸引。检查碎块后，你发现它的表面上还残留着镌刻的符文。\n\n这块碎片似乎与圣光军团用来为军械供能的阿古尼特水晶类似。这块水晶会不会属于那个很久以前，为逃出阿古斯而战的艾瑞达？\n\n也许法瑞娅队长知道更多关于这块水晶的情况。>', '', '', '', '', '', '', 25549),
(48203, 'zhCN', '燃烧王座', '在安托兰废土上方使用执政团之冠打开通往安托鲁斯的道路。', '时机成熟了，$n，可以开始攻打安托鲁斯了。我们多年的奋斗，以及亲友所作出的牺牲，终于让我们走到了今天。$b$b我们会用圣光裁决者轰开这座诅咒堡垒的高墙，踏平他们的权力中心。我们会成为燃烧军团的终结者。$b$b你在这场战争中居功至伟，这份荣耀应该属于你。激活执政团之冠吧，让我们一起完成这份使命。', '', '', '', '', '', '', 25549),
(48202, 'zhCN', '支援隐匿洞穴', '与隐匿洞穴的伊利丹谈一谈。', '有了你建立的据点，我们就能与战地特工接洽了。$b$b我们上次到这里来执行任务时，在东北方建立了一个堡垒，目前应该还能起到防御的作用，但战场局势瞬息万变。$b$b伊利丹已经过去查看形势了。我建议你也过去，看看他需不需要你帮忙。', '', '', '', '', '', '', 25549),
(48201, 'zhCN', '增援圣光据点', '与圣光据点的奥蕾莉亚谈一谈。', '既然我们已经站稳脚跟，就可以与战场上的士兵汇合了。$b$b我们在南面有座圣光军团的营地，燃烧军团把他们最强的战士储藏在那附近，并让他们处于某种静滞状态。$b$b奥蕾莉亚去侦察那片区域了。找到她，看看她收集到了什么情报。', '', '', '', '', '', '', 25549),
(48200, 'zhCN', '立足之地', '前往安托兰废土，放置光铸道标。', '我和奥蕾莉亚以前侦察过这片地区，当时身边还有几个精英战士。我们在目前位置的两侧扎下了营地，但我担心他们会受到猛烈攻击，需要援助。$b$b我们的首要任务是在维迪卡尔正下方设置一个传送道标。我们可以从那里前往两个作战前线。$b$b你准备好前往地面的话，就与罗姆尔谈一谈。', '', '', '', '', '', '', 25549),
(48199, 'zhCN', '灼燃之心', '使用导航控制台前往安托兰废土。', '泽拉的死是一次沉重的打击，对图拉扬来说尤其如此。但即使是圣光之母也不能强迫我们接受命运。\n\n如果伊利丹换一种方式拒绝她就好了……但我其实也曾经面对过纳鲁强加给我的选择。\n\n我们不能为此而分心，我们的使命还在等待我们。现在圣光军团的生还者加入了我们，我们可以加紧攻击了。\n\n我们要在安托兰废土站稳脚跟，这样才能攻击燃烧王座。时候到了，绝不能让萨格拉斯的邪恶计划成功！', '', '', '', '', '', '', 25549),
(48192, 'zhCN', '焦油喷吐者', '', '', '', '', '', '', '', '', 25549),
(48107, 'zhCN', '启迪印记', '返回维迪卡尔，放置启迪印记。', '这件圣物太过强大，不能放在外面。$b$b我们必须立即将其送回维迪卡尔。先知明白该怎么做。$b$b我非常感谢你，$n。没有你的话，这一切都不会成功。夸拉姆绝不会让我靠近印记。也许某天，我可以跟你讲讲那个故事。', '', '', '', '', '', '', 25549),
(48106, 'zhCN', '不留情面', '', '', '', '', '', '', '', '', 25549),
(48105, 'zhCN', '同行评议', '', '', '', '', '', '', '', '', 25549),
(48101, 'zhCN', '公开演讲', '', '', '', '', '', '', '', '', 25549),
(48099, 'zhCN', '敌意回响', '', '', '', '', '', '', '', '', 25549),
(48098, 'zhCN', '花园害虫', '', '', '', '', '', '', '', '', 25549),
(48091, 'zhCN', '背弃者瓦加斯', '', '', '', '', '', '', '', '', 25549),
(48081, 'zhCN', '飘浮的废墟', '前往玛凯雷。', '我们本就知道燃烧军团是个可怕的敌人，但最近的事件表明，我们的力量还不够强大，难以支持下去。我们付出了如此巨大的代价，这样的关键时刻已不容失败。$b$b我知道我那古老的家乡玛凯雷有一件圣物，可能就是我们的出路。我们必须让维迪卡尔离开阿古斯星球表面，前往悬浮在上空的废墟。$b$b也许我们能在那里找到我们急需的出路。', '', '', '', '', '', '', 25549),
(48078, 'zhCN', '平衡力', '收集恶魔皮革和光纹布，然后使用恩斯特拉的制革油制作$1oa块净化的恶魔皮革。', '很久以前，我可以用这片大地上的野兽制作出精美的物品。但后来，燃烧军团的降临灭绝了所有那些神奇的动物。$b$b现在我只能使用它们被污染的皮毛来为盟友制作护甲。但我还是想出了净化污秽的办法。$b$b我们所使用的布料由灌注着圣光能量的线织成。我发明了一种油，搭配布料可以净化皮革，以供使用。$b$b拿上我的油，自己去试试吧。', '', '', '', '', '', '', 25549),
(48076, 'zhCN', '冠冕成就', '为沃雷尔打造一顶天界王冠。你可以通过采集阿古斯的矿石来选矿、与其他玩家交易、或者从拍卖行得到材料。', '差点永远失去这本书后，我意识到我不该将这些知识保存在一个地方。我愿意将它们传授给你，$n。$b$b我最近的几项设计尤其令我自豪。我将它们称为天界王冠。每顶皇冠都使用不同的宝石组合，从而实现不同的强大效果。$b$b我来教你怎么加工，以及不同的宝石组合如何获得不同的效果。', '', '', '', '', '', '', 25549),
(48075, 'zhCN', '绚丽的钥匙', '前往沃雷尔的家，使用从天界金中选矿获得的六种宝石打开他的箱子。找到沃雷尔的珠宝加工书，并带回维迪卡尔交给他。', '$n，听说你是个珠宝匠。我也是个切割大师，但我很怕我的设计会落入军团之手。$b$b我匆忙离开老家，原本还想着回去，但如今恐怕是没这个机会了。你瞧，我将我最珍贵的宝物——一本珠宝加工设计书落在家里了。$b$b但你不一样，你很强大，你可以一路披荆斩棘前往我的老家，找回我的书！$b$b不过我用一个特殊的箱子把它锁起来了，需要用这片大地上的宝石去解锁。每种宝石都需要一颗，才能打开箱子。', '', '', '', '', '', '', 25549),
(48074, 'zhCN', '将我笼罩', '前往阿尔诺花园，找回凯拉的光纹织布机。', '赶到泽尼达尔的时候，我丢失了一件珍贵的工具，我的光纹织布机。没有它，我为盟友制作强力物品就得耗费更长的时间。$b$b但你很强大，比我强多了。也许你可以帮我个忙。如果你碰巧路过阿尔诺花园，是否可以帮忙找回我的织布机？$b$b届时我将非常乐意与你分享我的光纹布纺织技术。', '', '', '', '', '', '', 25549),
(48069, 'zhCN', '钳子在呼唤', '去达拉然找钳工蒂迪。', '$n，达拉然的钳工蒂迪正在找你。你最好去看看她近期的成果。据说挺高端的。', '', '', '', '', '', '', 25549),
(48065, 'zhCN', '外星探索', '在你的地图上标记的位置使用电离地理记录仪。完成后回去找蒂迪。', '$n，我听说你已经去过天上那颗巨大的绿色星球了。据说那里也是恶魔肆虐。$b$b我在想，我们也许可以为它再组装一台虫洞发生器。让那颗星球上的快速移动变得更加容易。$b$b问题是我们必须获得地形的数据。虽然我愿意亲自去，但是，呃……我必须留在这里看店。不能把店铺留给这些蠢货。$b$b拿上这个，去给我记录点数据回来，行不？', '', '', '', '', '', '', 25549),
(48056, 'zhCN', '严厉的月亮', '帮助霍巴特在达拉然城内校准原型款减重便鞋。', '我之前思考着，要如何让大家在阿古尔还是那什么的星球上面自由行动呢？因为我觉得那里的重力应该和我们的不一样。于是我想出了一款装置，可以装在你的鞋子或者蹄子，或者你要在那里穿的其他东西上面。$b$b后来我听说，那个星球的重力……和我们这儿完全一样！$b$b不管如何，我想，我可以先把原型款做出来。你愿意搭把手吗？也许等我们做出来以后，你可以把它卖给孩子们什么的。', '', '', '', '', '', '', 25549),
(48055, 'zhCN', '天界金之力', '制作一件天界金胸甲。你可以通过阿古斯的矿石开采、与其他玩家交易或从拍卖行得到材料。', '看来我的护甲似乎引起了你的兴趣。这是由阿古斯最高级的材料：天界金打造的。我其实最擅长制作胸甲。$b$b我可以教你制作，但恐怕你必须自带材料。我们的矿石存量太少，而且不能平白消耗。$b$b但这是所需材料的清单，以便你去收集……', '', '', '', '', '', '', 25549),
(48054, 'zhCN', '重压船锚', '将一箱邪能页岩带给锈水港的克鲁达·雷手。', '$n，希望你能帮我一个小忙。锈水港的海军舰队订购了大量邪能页岩，用于船舰的补给。$b$b我现在正忙着指挥采集工作，而我的信使也都没回来。不知道你是否愿意帮我把这批货送去给他们？$b$b我听说达拉然的风行者圣殿里开有通往奥格瑞玛的传送门，所以这段路应该不会太漫长什么的。', '', '', '', '', '', '', 25549),
(48053, 'zhCN', '重压船锚', '将一箱邪能页岩带给暴风城港口的沃尔科特·桑顿。', '$n，希望你能帮我一个小忙。暴风城港口的海军舰队订购了大量邪能页岩，用于船舰的补给。$b$b我现在正忙着指挥采集工作，而我的信使也都没回来。不知道你是否愿意帮我把这批货送去给他们？$b$b我听说达拉然的灰牙之地里开有通往暴风城的传送门，所以这段路应该不会太漫长什么的。', '', '', '', '', '', '', 25549),
(48042, 'zhCN', '操作顺序', '与恩斯特拉对话，学习更高效的阿古斯野兽解剖法。', '<毛皮的数量充裕多了，但你只来得及收集到少数未被污染的牙齿和爪子。>$b$b<由于不知道该如何提高牙齿和爪子的收集效率，你还需要再找维迪卡尔的恩斯特拉谈一谈。>', '', '', '', '', '', '', 25549),
(48041, 'zhCN', '大块皮革', '和恩斯特拉对话，学习更高效的恶魔皮革剥离方法。', '<虽然你的剥皮速度快多了，但还是有很多皮革在剥下前被污染。>$b$b<恩斯特拉也许知道该如何在皮毛被污染前剥离出更多皮革。>', '', '', '', '', '', '', 25549),
(48040, 'zhCN', '被污染的碎皮', '在维迪卡尔上找到某个也许可以教你剥制恶魔皮革的人。', '<当你开始小心翼翼地剥皮时，你发现尸体的腐烂很快污染了皮毛。>$b$b<剥下皮后，你只能使用其中一小部分的皮革，而且气味非常难闻。也许维迪卡尔上有人知道这种恶臭皮毛的事情。>', '', '', '', '', '', '', 25549),
(48039, 'zhCN', '平衡力度', '与卡米尔对话，了解如何从天界金矿层中开采更多矿石。', '<逐渐深入矿层底部之后，你只能找到小块矿石和碎片。虽然总和起来的话，数量应该够用。>$b$b<卡米尔也许有办法防止这种情况的发生。>', '', '', '', '', '', '', 25549),
(48038, 'zhCN', '别闷头下镐', '与卡米尔对话，了解如何从天界金矿层中开采更多矿石。', '<虽然你已经学会了暴露矿石，但大型结块似乎依然牢牢地嵌在周围的岩石中。开采这种矿石也许无法得到你所需要的纯净天界金。>$b$b<也许卡米尔可以告诉你该如何挖掘矿层中的这种矿石。>', '', '', '', '', '', '', 25549),
(48037, 'zhCN', '天界金矿层结块', '在维迪卡尔上找到某个也许可以教你开采天界金矿层的人。', '<一开始，你以为矿石表层是镜面，反射着头顶上的漫天繁星。挖下一大块之后，你发现原来矿石本身的质地便如星光一般。>$b$b<也许维迪卡尔上有人可以指导你如何更高效地开采这种矿层。>', '', '', '', '', '', '', 25549),
(48036, 'zhCN', '完美精准', '和卡米尔对话，了解是否能够再提高开采天界金矿脉的效率。', '<虽然你已经学会如何最大限度地开采矿脉，但矿脉的核心却总是无法使用。近距离观察之下，你发现你击打的地方就是核心开裂的地方。>$b$b<看来还需要再拜访卡米尔一次，以解决这个问题。>', '', '', '', '', '', '', 25549),
(48035, 'zhCN', '更精准的角度', '和卡米尔对话，了解是否有办法提高开采天界金矿脉的效率。', '<看着挖掘矿脉后产生的天界金粉尘，你不禁思考，是否有办法能够防止矿脉在挖掘时碎裂。>$b$b<也许卡米尔可以和你分享一些经验。>', '', '', '', '', '', '', 25549),
(48034, 'zhCN', '天界金矿脉结块', '在维迪卡尔上找到一个可以教你开采天界金矿脉的人。', '<你挖向矿石的时候，镐头发出一声巨响，一小块碎石掉落在地。按照这种速度，想从这处矿脉挖出足够的矿石，将需要花费一整天的时间。$b$b也许有人可以指导你如何正确地开采这种矿石？>', '', '', '', '', '', '', 25549),
(48029, 'zhCN', '它的心', '询问弗恩，了解星辰之耀的发光根茎。', '<与星辰之耀打了一段时间的交道之后，你对它的根茎产生了兴趣。紧紧缠成茧形的根茎里，细小的光斑穿透裂隙照射出来，散发出莹莹微光。$b$b也许弗恩知道这种光芒是什么。>', '', '', '', '', '', '', 25549),
(48028, 'zhCN', '年轻的抵抗', '询问弗恩，了解如何处理较为鲜嫩的星辰之耀。', '<开始采集之后，你发现一些较为鲜嫩的花朵依然抵制你的接触，拒绝投降。也许弗恩知道该如何应对新开的花朵。>', '', '', '', '', '', '', 25549),
(48027, 'zhCN', '阿古斯之耀', '在阿古斯找到一个可以教你处理星辰之耀的人。', '<你从地上摘起那朵花。如此纯净的东西竟然还能在这颗星球上生长，真是令人惊奇。你感觉到其中弥漫出微弱的力量，随后消散殆尽。>$b$b<随着它在手中凋零，你不禁思考，在这片被圣光遗忘的土地上，是否会有人知道该如何处理这种珍贵的草药。>', '', '', '', '', '', '', 25549),
(48021, 'zhCN', '克罗米', '与龙骨荒野的克罗米的友谊达到“时空跃迁者”级别。', '$n，是你吗？$b$b我相信时间线里出现了怪事。我需要你的帮助！$b$b到龙眠神殿来找我吧，就在龙骨荒野。我会亲自带你看看 。', '', '', '', '', '', '', 25549),
(48016, 'zhCN', '提升炼金', '把$1oa株星辰之耀，$2oa个源生萨格里特以及一枚地狱火炼金石交给弗恩。', '我看到某些经过我们营地的炼金师携带着一种有趣的饰品。我记得他们好像称之为……“炼金石”？$b$b我能感觉到那些石头散发的力量，但它们似乎被邪能污染了。这颗星球上生长的草药尤其擅长净化腐蚀。我用它来净化那些经常出现在草药里的源生萨格里特。$b$b我敢肯定，如果我们对那些石头使用净化过的萨格里特，就能够提升其中蕴藏的力量。', '', '', '', '', '', '', 25549),
(48013, 'zhCN', '反追踪', '消灭安尼赫兰熔池的$1oa头邪焰清道夫。', '$n，我有没有跟你讲过我的追踪药水？我们的侦察兵用它追踪恶魔，尤其是他们的“魔犬”。$b$b那些怪物特别喜欢吞噬附近的星辰之耀，导致我们的草药库存一直无法补充。$b$b如果你能削减它们的数量，我们就不用去其他地方补充库存，那可就帮了大忙了。他们在安尼赫兰熔池附近大量徘徊。$b$b为了感谢你的帮助，我会将这种药水的配方送给你。', '', '', '', '', '', '', 25549),
(48002, 'zhCN', '补给有限', '前往石化森林，回收$1oa个用过的瓶子。', '你好，$n。很高兴能够再次见到炼金术师同行。$b$b我一直在为我们的营地提供对付恶魔所需的药水，但我的库存最近总是不太足。侦查兵们平时出去之后，都会带着空瓶子回来，但最近回收到的却很少。$b$b我已经在尽可能地重复利用了，所以你瞧，这些瓶子对我非常重要。如果你愿意去野外把我的瓶子找回来，我可以教你一种药水，在对抗恶魔的时候很有帮助。', '', '', '', '', '', '', 25549),
(47995, 'zhCN', '光明正大', '找到“神射手”巴拉特、大守备官索沃斯和剑圣特拉蒙。', '我的士兵们还在战场上，$n。$b$b我需要你去找到巴拉特、索沃斯和特拉蒙。军团突然出现在我们面前时，他们正在为维伦清理这片地区。$b$b去通知他们，现在的命令是立即回到先知身边。$b$b已经没时间小心翼翼了。一小股敌人正挡在我们之间。不必手下留情。$b$b圣光保佑你。', '', '', '', '', '', '', 25549),
(47994, 'zhCN', '构筑联结', '', '', '', '', '', '', '', '', 25549),
(47993, 'zhCN', '高塔之主', '击败领主纳斯拉克斯。', '作为许多年前将阿古斯献给燃烧军团的犒赏，领主纳斯拉克斯得以统治这座要塞。\n\n毫无疑问，他非常强大，但久居高位的他也日渐刚愎自用。\n\n尽可能利用他的傲慢和战争机甲的火力。我们很快就要突袭庭院了！', '', '', '', '', '', '在维迪卡尔与图拉扬见面。', 25549),
(47992, 'zhCN', '正义黎明', '使用光铸战争机甲占领复仇者庭院。', '感谢你的努力，我们的敌人已陷入混乱，他们的防御工事也无法运作了。\n\n我们必须在尖塔底座稳住脚步，然后收紧围绕在他们指挥官脖子上的铰链。\n\n你的出色表现早已赢得了使用战争机甲的资格。通道清理完成后，我们将听从你的指挥。', '', '', '', '', '', '', 25549),
(47991, 'zhCN', '黑暗阴谋', '拆毁$1oa座哀伤尖塔。', '艾瑞达极其擅长操纵遍布这个世界的邪能。那些没在制造活化武器的恶魔制造出了其他武器，例如哀伤尖塔。\n\n这些尖塔阻碍了我们的推进，就算是小型部队也无法抵达要塞主楼。我们必须拆毁一定数量的尖塔，清出一条道路后才能继续前进。', '', '', '', '', '', '', 25549),
(47990, 'zhCN', '一丝邪能', '收集一枚完美的邪能核心。', '我们的战争机甲就快完成了！现在只需要一股猛烈的电流就能重新激活它的系统。\n\n下面那个池子里的术士正在用邪能灌注阿古斯的碎片，以打造活化攻城武器。如果你可以带一枚回来，我们就能用它启动战争机甲的审判核心！', '', '', '', '', '', '', 25549),
(47989, 'zhCN', '末日使者', '击杀赫拉迪卡夫人和妖女阿波崔丝。', '我们发现了一个大好机会。\n\n我们的侦察兵在西部的邪能之池中发现了两个破坏魔女祭司，她们正在强化军团的战争物资。\n\n萨格拉斯的近臣从不离开安托鲁斯的高墙。如果能干掉她们，我们也许可以在那些最接近黑暗泰坦的人群中间散播恐慌。', '', '', '', '', '', '', 25549),
(47988, 'zhCN', '混沌理论', '消灭$1oa名纳斯拉克森裂肉者、纳斯拉克森末日射手或贪婪的猎魂犬，以及$2oa名纳斯雷兹姆怨毒领主。', '虽然力量强大、数量众多，但即使是燃烧军团也需要秩序。扰乱他们的秩序……他们就会化为乌合之众。\n\n计划很简单。让他们的军队陷入混乱，胜利就属于我们了。', '', '', '', '', '', '', 25549),
(47987, 'zhCN', '预防措施', '使用先知护符，净化$1oa名阵亡的圣光军团战士。', '军团的邪恶无穷无尽。每打赢一场战斗，每攻占一个世界，都会为他们的战争机器贡献更多灵魂燃料。\n\n他们还没腐化这座要塞里所有阵亡的战士，但那恐怕也只是个时间问题。拜托，请带着这枚护符进入要塞，用它净化你所遇到的尸体。\n\n他们的命运不应如此悲惨。', '', '', '', '', '', '', 25549),
(47986, 'zhCN', '过往的伤痕', '找到一个符咒阵列、一件守备官装甲和一枚审判核心。', '圣光军团的战争机甲已在阿古斯获得过无数胜利。这些机甲虽然力量强大，但并非所有加入战斗的机甲都能平安归来。\n\n我对这部机甲所做的调整应当能为我们提供所需的优势，但我目前仍然缺少几个关键的组件。\n\n纳斯拉克斯还残留着过往战斗的残迹，我们可以加以利用。如果你找到我所需要的组件，军团就将再次承受我们的怒火。', '', '', '', '', '', '', 25549),
(47967, 'zhCN', '阿古斯套羊手', '将$1oa头野生岩羊带给首席骑兵贾伊德。', '如果没有我们的岩羊，即使面对最低级的军团小队，我的战士也毫无胜算。如果你可以抓几头带回来，那么我的战士就能更好地保护人民了。', '', '', '', '', '', '', 25549),
(47953, 'zhCN', '分选者泰瑞克', '', '', '', '', '', '', '', '', 25549),
(47906, 'zhCN', '克罗米之死', '在场景战役“克罗米之死”中一次性阻止针对克罗米的全部八次攻击。', '看来我们得阻止针对我的全部八次攻击，而且要在十五分钟内完成。\n\n就算是对我来说，这段时间也不算多。\n\n可要是还有人能够做到的话，那就是我们了。你准备好了吗，$n？', '', '', '', '', '', '', 25549),
(47904, 'zhCN', '保卫真正的未来', '在场景战役“克罗米之死”中一次性阻止来自黑曜石、红玉、碧蓝和翡翠巨龙圣地的攻击。', '我知道你在想什么，$n。我可不是因为怕死才请你帮忙的。\n\n我请你帮忙是因为，我不应该这么死。我确实会死——我早就预见到了！但我的死期还早着呢。而且，为了私人原因而扰乱时间流——这违反了我们青铜龙军团的宗旨。\n\n让我们阻止对全部四座巨龙圣地的攻击。这应该管用。', '', '', '', '', '', '', 25549),
(47895, 'zhCN', '伯特的机器人', '在宠物对战中击败伯特。', '如果我要清理诺莫瑞根，就必须准备好面对各种各样的老鼠、蟑螂，可能还有可怕的变异鼠蟑。\n\n我想说的是，我得测试这些机器人！需要进行实地检测才行！\n\n你的宠物准备好进行代码审查了吗？', '', '', '', '', '', '', 25549),
(47892, 'zhCN', '进攻堡垒', '前往命运角。', '我们已经在纳斯拉克斯要塞附近稳固了阵地。那应该是燃烧军团在阿古斯重要的军事要塞之一。\n\n立即对其发动猛烈攻击，这可能是我们扭转战场形势的唯一机会。', '', '', '', '', '', '与命运角的图拉扬汇合。', 25549),
(47891, 'zhCN', '坏消息', '返回维迪卡尔与图拉扬会面。', '艾泽拉斯送我们到这里来是对的，$n。我们必须阻止萨格拉斯的计划，否则最后我们可能连艾泽拉斯这个家都没有了。$B$B你应该回到图拉扬那里，把你看到的情况告诉他。我会呆在这里，看看能否找到其他能给我们提供帮助的东西。', '', '', '', '', '', '向维迪卡尔的图拉扬复命。', 25549),
(47890, 'zhCN', '折磨的幻象', '激活圣石，和麦格尼一起观看幻象。', '来到阿古斯之后，我一直听到低语声。就像艾泽拉斯的低语一样，只不过……不是她的声音。\n\n我很确定，阿古斯的泰坦想要和我们取得联系！\n\n破碎者在附近藏有一个圣物。哈顿说他们是就是从那里听到低语的……我想它可能与阿古斯本身有着某种联系！\n\n就在这个房间。看看我们能发现什么东西。', '', '', '', '', '', '', 25549),
(47889, 'zhCN', '代言人的召唤', '在克罗库营地与麦格尼见面。', '麦格尼叫你到克罗库营地和他汇合。他觉得他发现的那些东西可以帮我们消灭燃烧军团的无尽大军。\n\n想要结束这场战争，我们就必须要利用一切能利用到的优势。你应该找到他的下落。', '', '', '', '', '', '到克罗库营地与麦格尼见面。', 25549),
(47883, 'zhCN', '最漫长的守望', '唤醒守门人。', '还好我们找了两种能量源。即使这些导体激活了，构造体还是没有反应。$b$b它可能有很长一段时间没被启动过了，也许跟玛凯雷在阿古斯上方飘浮的时间一样久。$b$b它守卫的时光多么漫长而孤独。$b$b<伊米拉看着构造体，沉默了片刻。>$b$b去吧，把它刺激一下，再加上一点魔法的爆发，应该就会起作用了。', '', '', '', '', '', '', 25549),
(47882, 'zhCN', '魔法的储存', '稳定8个不稳定的能量导体。', '我有一个主意。这个构造体对我们有用。我们只需要把它唤醒就好。$b$b我们曾经把巨大的能量存储在遍布学宫的导体之中。它们仍然可以运作，但也仅此而已。$b$b拿着这个。$b$b<伊米拉递给你一个闪闪发光的水晶。>$b$b它可以造成小型的魔法爆裂，帮助稳定不稳定的能量导体。我想存的能量应该可以足够用于8个导体。$b$b稳定几个导体后，我们应该就可以访问整个网络了。', '', '', '', '', '', '', 25549),
(47867, 'zhCN', '海上潜行', '与女伯爵莉亚德琳谈谈以启航前往埃索达。', '德莱尼人打造了一搜飞船，可以把我们安全地送到阿古斯。就在我们说话的时候，他们正在秘蓝岛聚集进攻部队。\n\n我们会从海上过去加入他们的队伍。燃烧军团肯定会盯着他们世界的入口。我们必须出其不意。\n\n你准备好了之后就跟我说。', '', '', '', '', '', '', 25549),
(47865, 'zhCN', ' 封印命运：成堆的荣誉印记', '', '', '', '', '', '', '', '', 25549),
(47864, 'zhCN', ' 封印命运：额外的荣誉印记', '', '', '', '', '', '', '', '', 25549),
(47858, 'zhCN', '安保措施：启动', '', '', '', '', '', '', '', '', 25549),
(47856, 'zhCN', '穿越宇宙', '消灭塔尔加斯。', '塔尔加斯。他曾经是我的盟友、朋友。$b$b离开阿古斯的时候，我还很信任他。我请求他找到那些愿意跟随我的人。$b$b我给了他所需的一切，他却背叛了我，杀害我的追随者。$b$b我不知道他内心深处的这种仇恨从何而来，但他的阴谋迫使我的人民从一个世界不断逃向另一个世界。他穿越宇宙不断追杀我们。$b$b这一切必须到此为止，$n。塔尔加斯必须死。', '', '作为基尔加丹手下的秘密狩猎大师，塔尔加斯一直在群星间追杀着德莱尼。', '塔尔加斯', '', '', '', 25549),
(47855, 'zhCN', '原本假如', '见证维伦的记忆。', '<维伦说话的同时仍然盯着雕像。>$b$b数千年之前，当我还年轻的时候，我做出了一个选择。$b$b这个选择让我的世界灰飞烟灭。这个选择导致我的人民被迫流亡。这个选择让我和我挚爱的兄弟永远分离。$b$b<维伦摇了摇头。>$b$b我不能离开，现在还不行。在我好好反思之前，我是不会离开的。', '', '', '', '', '', '', 25549),
(47854, 'zhCN', '大主教的愤怒', '干扰阿尔诺花园中的军团部队。', '军团所到之处，暴力总是不可避免。$b$b<图拉扬举起了剑，表情严肃。>$b$b他们拦在了我们和维伦之间。除非我们先发制人，否则他们一定会找到他。现在还不是撤退的时候。$b$b团结一致，我们就可以在他们的部队中散布混乱。', '', '', '', '', '', '', 25549),
(47853, 'zhCN', '侧翼合击', '关闭3个军团传送门。', '我会指挥法瑞娅的副官，然后我们一起护送维伦前往知识桂冠。他的任务决不能失败。$b$b我们面临着一个老对手，一个圣光军团对阵了无数次的对手。塔尔加斯会想办法拦住我们，阻止我们撤退。$b$b你绝对不能让他们得逞。弄清楚他的部队是如何过来的，并将其阻断。我们最需要的是时间，杀进去然后再撤出。$b$b我们都指望你了。', '', '', '', '', '', '', 25549),
(47851, 'zhCN', '封印命运：荣誉印记', '', '', '', '', '', '', '', '', 25549),
(47844, 'zhCN', '疯狂回归', '', '', '', '', '', '', '', '', 25549),
(47835, 'zhCN', '命运之手', '到刃拳海湾和前往埃索达的护卫汇合。', '"$p,\n\n我们已经赢得了许多对抗燃烧军团的战斗，但这一次我们要彻底终结这场战争。\n\n最后的准备工作已经准备就绪，准备向阿古斯出发。\n\n快点赶去刃拳海湾。那里有艘船正在等着你，将会把你和你的盟友带往秘蓝岛。"', '', '', '', '', '', '', 25549),
(47828, 'zhCN', '疯狂回忆', '', '', '', '', '', '', '', '', 25549),
(47810, 'zhCN', '阴暗的梦', '在翡翠巨龙圣地击杀萨拉斯·维索恩。', '翡翠巨龙圣地的古树正在梦境中遭受折磨。伊瑟拉已经不在了，而我分身乏术，没法亲自去调查。你能否帮我净化翡翠巨龙圣地的梦魇？', '', '', '', '', '', '', 25549),
(47809, 'zhCN', '魔网中的黑暗', '在碧蓝巨龙圣地杀死虚空巨怪。', '在我族群的巨龙圣地，有一股奇异而黑暗的能量正在扰乱那里的魔网。你是否有时间去调查一下？', '', '', '', '', '', '', 25549),
(47808, 'zhCN', '行尸走肉', '在红玉巨龙圣地击杀塔拉·冰寒。', '你好，$r。我知道你来这里是要帮青铜龙，但我也要请你做一件事。$b$b红玉巨龙圣地被亡灵占领了。我的圣地守护者们没有准备，如果没有人尽快去帮助，我很可能会失去他们。你愿意帮我们吗？', '', '', '', '', '', '', 25549),
(47807, 'zhCN', '我担心我的朋友', '在黑曜石巨龙圣地杀死佐拉赛德。', '我听说，黑龙的巨龙圣地出了点麻烦。我知道，我是青铜龙，不过那又如何！我偶尔也会担心他们！他们的脾气也不总是那么暴躁。$b$b如果你正好要过去的话，你能不能处理一下……在那边引发混乱的东西？', '', '', '', '', '', '', 25549),
(47793, 'zhCN', '变质的样品', '前往破碎群岛的达拉然，把变质的样品交给奥法工匠维迪尔。', '<你捡起一瓶粘稠的漆黑液体。里面的东西对你的触摸起了反应，它沸腾起来，疯狂地冒着气泡，然后又迅速平静下来，发出持久不灭的光。在这个状态下，这种物质看起来很像魔力酒，但刚才的反应让你想起分解抑魔金的过程。$b$b你把瓶子放进背包。达拉然城里某个熟悉抑魔金熔炉的人可能了解得更多。>', '', '', '', '', '', '', 25549),
(47791, 'zhCN', '动荡的能量', '把$1oa个沸腾的精华带给奥法工匠维迪尔。', '阿曼苏尔的能量变得越来越不稳定，这非常令人不安。我们必须进一步调查这个问题。$b$b是军团的腐化导致它变得不稳定吗？不，这个因素出现太晚，不足以造成影响。肯定是别的什么东西……$b$b<维迪尔非常心不在焉，说到一半就停住了，也没有正面看着你。>', '', '', '', '', '', '', 25549),
(47790, 'zhCN', '动荡的能量', '把$1oa个沸腾的精华带给奥法工匠维迪尔。', '原本限制在暗夜井中的能量一经释放……便导致破碎群岛各地阿曼苏尔遗留下的影响力变得错综复杂。很遗憾，我之前的研究成果已经无效，正如同这个瓶子里的东西一样。$b$b我必须弄清楚这些变化的起因！拜托了，请你给我多带来一些样本，让我继续研究。无需多言，一旦我的研究获得突破性进展，你也会跟着获利。', '', '', '', '', '', '', 25549),
(47773, 'zhCN', '炮火蔽日', '破坏联盟攻城火炮。', '哦！是我！你是$n，对吧？我记得这里！$b$b我好像被困在部落和联盟的战斗之中，一般来说，这不是什么大事，只不过每当我想飞走，那台大炮似乎就瞄准我不放。$b$b你能帮我解决掉它吗？', '', '', '', '', '', '', 25549),
(47772, 'zhCN', '炮火蔽日', '破坏部落攻城火炮。', '哦！是我！你是$n，对吧？我记得这里！$b$b我好像被困在部落和联盟的战斗之中，一般来说，这不是什么大事，只不过每当我想飞走，那台大炮似乎就瞄准我不放。$b$b你能帮我解决掉它吗？', '', '', '', '', '', '', 25549),
(47771, 'zhCN', '找到“神射手”的下落', '找到“神射手”巴拉特。', '想要解救泽拉，我们得需要更大的炮。$b$b炮就在靠近泽尼达尔的那些摧毁的碉堡里。如果是巴拉特在跟进这项任务，他肯定已经开始调查这片区域了。也许他已经找到了飞船的主炮。$b$b如果你去那边，请确保他还活着，好吗？', '', '', '', '', '', '', 25549),
(47754, 'zhCN', '轻度烧烤', '使用圣光裁决者摧毁挡住泽尼达尔入口的石堆。', '$n，能听到我说话吗？很好。$b$b圣光裁决者已经安装到维迪卡尔上了。我们应该马上就能使用它的力量。$b$b我们可以用它来清理挡住泽尼达尔的石堆，还能消灭敌人。$b$b对待任何新技术，我们都得先测试一下。要全面测试。我相信那里有足够多的目标。', '', '', '', '', '', '', 25549),
(47750, 'zhCN', '给埃姆雷', '把腌制鹿肉干交给埃姆雷·尼尔。', '不过，我们这里食物很充足。如果你有胆量上街，请把这些鹿肉交给酒馆里那个傻瓜。$b$b告诉他，是孩子们给他的。', '', '', '', '', '', '', 25549),
(47747, 'zhCN', '以火攻毒', '找到一个燧石点火器和一段沉重的草绳。', '我还有最后一个要求，陌生人。我看到外面的情景了，我也听说过这场“瘟疫”的事情。我不想不经反抗就束手待毙。$b$b我的酒吧后面有很多朗姆酒，足够把整个酒馆点燃，但我没有能让我安全放火的工具。帮我找一块燧石和一段绳子，我就把斯坦索姆小巷的钥匙给你。', '', '', '', '', '', '', 25549),
(47746, 'zhCN', '躲藏好', '找到一把翻新的军用步枪、初级布绷带和腌制鹿肉干。', '你……你看见了吗？阿尔萨斯王子刚刚把那个人杀了！真残忍！就在大街上！$b$b<梅丽娜恢复了镇静。>$b$b我得保护孩子们。请你们帮帮我，外来者。我需要一把枪、绷带、还有一些鹿肉干。$b$b孩子们！大家都进屋去！', '', '', '', '', '', '', 25549),
(47745, 'zhCN', '对，绝对是给孩子们的', '把金盏菊花束交给孤儿院长梅丽娜。', '我不知道你见没见过孤儿院长梅丽娜，她就像一位女神降临，令洛丹伦散发出夺目的光彩。她的头发，她的颧骨，她的……$b$b……总之，这些花要送给她孤儿院里的孩子们。告诉梅丽娜，这些花是我送的。送给孩子们。', '', '', '', '', '', '', 25549),
(47744, 'zhCN', '烟、肉、漂亮的花', '找到一些腌制鹿肉干、弗拉斯的特级烟丝和一捆金盏菊花束。', '城镇后面已经封锁了，孩子。没错，我有钥匙，但我不认识你。$b$b<埃姆雷小心翼翼地拍了拍口袋。>$b$b听好，我想帮你这个忙。你看起来是个诚实的人。帮我弄点鹿肉、烟草和一束黄色鲜花，我有可能会给你破个例。', '', '', '', '', '', '', 25549),
(47743, 'zhCN', '光与影之子', '与图拉扬谈一谈，开始复活泽拉。', '是时候了，$n。$b$b泽拉回到了我们身边。我们有了圣光之心。我们有了她的救世之星。$b$b来吧，我们来修复她吧。我们来开辟一条崭新的光明之路，和敌人战斗到底。$b$b你准备好开始后就跟我说。', '', '', '', '', '', '', 25549),
(47728, 'zhCN', '恶毒者泰勒斯塔', '', '', '', '', '', '', '', '', 25549),
(47727, 'zhCN', '艾格文之路', '从萨格拉斯之墓的戒卫侍女身上收集4个守护者封印残片（史诗难度）。', '在我们封印墓穴时，我将禁锢萨格拉斯的最后一块封印残片交给了戒卫侍女。如果你能得到它，就能在墓穴中随意穿行了。但我不知道那位守护者怎么样了，你得做好最坏的打算。', '', '', '', '', '', '', 25549),
(47726, 'zhCN', '艾格文之路', '从萨格拉斯之墓的戒卫侍女身上收集4个守护者封印残片（英雄难度）。', '在我们封印墓穴时，我将禁锢萨格拉斯的最后一块封印残片交给了戒卫侍女。如果你能得到它，就能在墓穴中随意穿行了。但我不知道那位守护者怎么样了，你得做好最坏的打算。', '', '', '', '', '', '', 25549),
(47725, 'zhCN', '艾格文之路', '从萨格拉斯之墓的戒卫侍女身上收集4个守护者封印残片（普通难度）。', '我们封印墓穴的时候，我把萨格拉斯的牢笼的最后一个碎片托付给了戒卫侍女。如果你拿到了碎片，你就可以在墓穴中自由移动。但我不知道守护者如今的状况，我担心情况有变。', '', '', '', '', '', '', 25549),
(47724, 'zhCN', '反包围', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(47709, 'zhCN', '诺莫瑞根马拉松', '奔向藏宝海湾。', '准备好参加今天的大赛了吗，$n？\n\n每一年，来自世界各地的侏儒都会齐聚一堂，从诺莫瑞根跑向藏宝海湾！\n\n这个活动会提醒我们，哪怕对我们来说，也没有够不着的目标！无论你跑得是快是慢，是独自前行还是与好友一起上阵，只要坚持到底，就能完成比赛！所以，抓紧时间热身吧，然后让世人看看我们侏儒的志气！', '', '', '', '', '', '', 25549),
(47707, 'zhCN', '邪能熔毁', '', '', '', '', '', '', '', '', 25549),
(47691, 'zhCN', '先知亦非先知', '找到维伦。', '我确信维伦就在附近。如果他被抓了，我们肯定会知道。$b$b还是一样，我们不能磨蹭。他为抗击军团的事业付出了许多，燃烧军团肯定一心想要找到他。如果他们得手，后果不堪设想。$b$b所以我要和你一起去。$b$b我们必须找到维伦，并帮助他找回知识桂冠。我们必须信任他的想法，否则一切都将万劫不复。', '', '', '', '', '', '', 25549),
(47690, 'zhCN', '污染者的遗产', '击败阿克蒙德并获取启迪印记。', '看来你没有那么容易就被吓倒。很好。$b$b你的表现获得了寻找印记的资格。我得说清楚，我只是允许你继续前进。我并不保证你会成功。$b$b最大的挑战在前方等着你。$b$b你必须前往裁判所，面对阿克蒙德本人。只有击败学宫的主人，你才有资格获得印记。$b$b很少有人能战胜这个障碍。希望他不会把你打成一团烂泥。', '', '阿克蒙德并不知道自己会成为污染者，但他对力量的追求也不是从萨格拉斯出现时才开始的。', '阿克蒙德', '', '', '', 25549),
(47689, 'zhCN', '守门人的挑战：坚韧', '完成坚韧试炼。', '我的主人阿克蒙德从来就不喜欢优柔寡断。$b$b他喜欢的教学方式是无尽的挫折和再三的惩罚。想要在他的手下获得成功，强大的信念是必不可少的。$b$b在学宫对面的尽头，你会看到一座大型建筑。进去后，你的目标就是克服面前的所有障碍。$b$b挣脱困境，我就相信你的意志足够强大，可以继续前行。', '', '', '', '', '', '', 25549),
(47688, 'zhCN', '入侵物种', '收集30个消化了一半的奥能。', '如果我对导体的看法是错的就麻烦了，所以我们最好再找一种备用的能量源。$b$b幸好我知道哪里可以找到。$b$b阿古斯当地的影豹是独居生物，但看来启迪者拥有的某种魔法吸引了很多影豹前来这里。$b$b没时间讲究环保了——影豹是靠吞噬能量为生的。$b$b杀掉它们，看看能否重新夺回一些它们吞噬的能量。', '', '', '', '', '', '', 25549),
(47687, 'zhCN', '守门人的挑战：精通', '击败大宰相加拉苏姆、大执政官薇拉拉和高阶启迪者阿尔贡。', '阿克蒙德只是被追求力量的欲望所吞噬。只有那些能配得上他的欲望的人才能在他的手下顺利发展。$b$b你将会迎战阿克蒙德最强大的学生。这三个人曾经在自己的领域强大无比，学宫现在仍然铭记着他们。$b$b他们的回响会试图杀了你。$b$b如果能击败这三个人，而且自己还能毫发未损，那么我就会认可你的力量。', '', '', '', '', '', '', 25549),
(47686, 'zhCN', '毫不低调的开端', '在奥秘学宫和大法师伊米拉见面。', '现在我们可以开始搜索执政团之冠了。先从阿克蒙德身上携带的碎片启迪印记开始。$b$b你可以在东方和北方找到阿古斯最伟大魔法学校的遗迹。阿克蒙德就是在那里学会了如何掌握奥术魔法。他的宝藏肯定藏在那里。$b$b毫无疑问，那里肯定有守卫。我们要利用法瑞娅部队的追踪技巧沿着这条线索追下去。', '', '', '', '', '', '', 25549),
(47685, 'zhCN', '守门人的挑战：机智', '收集敏锐碎片、狡黠碎片和欺诈碎片，并将其组合成一个机智印记。', '阿克蒙德对他的学生期待很高。只有最富想象力和最机敏的智者，才能真正理解我们魔法最深处的奥秘。$b$b我怀疑你是否能理解。$b$b左边的道路会带你前往三个雕像。用它们可以收集机智印记。$b$b为了让这次试炼保持公正，我不会给出提示。如果真的有奇迹，而你居然能成功，那么我会正式认可你的……才华。', '', '', '', '', '', '', 25549),
(47663, 'zhCN', '沙塔斯的适时召唤', '与沙塔斯的沃尔姆见面。', '炽热之星在这轮循环里构成了古怪的星象，在寰宇间发出呼喊。去找沙塔斯的贤者沃尔姆，帮她一把。', '', '', '', '', '', '', 25549),
(47654, 'zhCN', '执政团之座：知识桂冠', '消灭鲁拉，获得知识桂冠。', '我们拥有了所需的一切，$n。$b$b奥蕾莉亚·风行者在执政团之座等着你的到来。$b$b不要单独行动，我的朋友。你需要和盟友一起行动才能取回知识桂冠……并面对如今的鲁拉。$b$b我会让维迪卡尔做好准备，等待你的归来。愿圣光为你照亮那片黑暗之地。', '', '', '', '', '', '', 25549),
(47653, 'zhCN', '圣光回归', '与图拉扬谈一谈，返回维迪卡尔。', '泽拉获救了！我们赢得了一场重要的胜利。$b$b圣光之母应该回到了维迪卡尔上。很显然，她想要跟你谈谈。要解释的事情太多了……$b$b罗姆尔现在应该可以把我们传送回船上了。你准备好后就告诉我。', '', '', '', '', '', '', 25549),
(47652, 'zhCN', '圣光之母', '在泽尼达尔内找到泽拉。', '我们必须确定圣光之母是否幸存下来了，$n。$b$b泽拉把她的心送到艾泽拉斯后被削弱了，但她是始祖纳鲁。她是圣光，不能熄灭。$b$b我们去泽尼达尔找她吧。愿圣光保佑，让她能回来继续指引我们。', '', '', '', '', '', '', 25549),
(47646, 'zhCN', '保护羊群', '', '', '', '', '', '', '', '', 25549),
(47645, 'zhCN', '虚空召唤者的卷轴', '找到隐藏在碧蓝巨龙圣地上空的虚空生物。', '<卷轴的碎片拼起来后，变成一段破烂、但能读懂的信息：>\n\n时候到了。祈咒将在碧蓝圣地上空举行。虚空将会吞噬青铜龙。主人有令，我们万死不辞。', '', '', '', '', '', '', 25549),
(47644, 'zhCN', '恶魔石核', '找到隐藏在黑曜石巨龙圣地的洞穴入口附近的恐惧魔王。', '<在恶魔石核的深处，一个恐惧魔王的影像说着不祥的话语：>\n\n遵命，主人。我们会在你指定的时间搞定这件事的。那头青铜龙绝对预料不到。我只需要在黑曜石巨龙圣地外来一下就够了。', '', '', '', '', '', '', 25549),
(47643, 'zhCN', '古树的智慧', '找到隐藏在翡翠巨龙圣地的萨特。', '三棵古树留下三个线索：\n\n“……巨大的梦魇……”\n\n“……去水边……”\n\n“……巨龙之掌……”\n\n或许攻击克罗米的人就躲在古树描述的地方？', '', '', '', '', '', '', 25549),
(47642, 'zhCN', '灵魂水晶', '找到隐藏在红玉巨龙圣地的大树内部的巫妖。', '<三个碎片整齐地拼成一块大型水晶。重组后，一个强大的巫妖的影像出现在水晶表面上。>\n\n<巫妖说道：>\n\n拖住红玉圣地守卫。我要从大树内部执行主人的进攻。', '', '', '', '', '', '', 25549),
(47641, 'zhCN', '抵抗的迹象', '搜索抵抗的迹象。', '我们的部队在守卫维迪卡尔的时候承受了巨大的损失，$n。我们需要盟友的支援。$B$B圣光军团以吸收燃烧远征的幸存者，充实自己的力量而著称。我们也必须这么做。$B$B我感到附近有你释放的燃烧军团的奴隶。我猜他们已经开始对抗自己的主人。$B$B如果你能和我一起前去寻找就太好了，$p。', '', '', '', '', '', '与克罗库营地外的先知维伦见面。', 25549),
(47627, 'zhCN', '复仇', '摧毁毁灭之冠的攻城武器。', '圣光军团不会白白牺牲。$B$B在我们摧毁他们攻城武器的同时，我们的部队会对主营地发起攻击。$B$B这是我们复仇的开始。', '', '', '', '', '', '', 25549),
(47625, 'zhCN', '斩断仪式', '', '', '', '', '', '', '', '', 25549),
(47607, 'zhCN', '奢华灯神', '在破碎群岛居民的口袋中找到稀有的宝物。', '有了我刚刚强化的灯，我能感应到距离更远、更加珍贵的物品了。它们就在这些精灵和恶魔的口袋里。去把它们给我弄来！', '', '', '', '', '', '', 25549),
(47606, 'zhCN', '忠诚就是最好的奖赏', '获得一千枚空气硬币。', '我有一个挑战要交给你，凡人。从我这里获得一千枚硬币。我相信到时候，我就能强化我的灯以及里面的幻象了。', '', '', '', '', '', '', 25549),
(47605, 'zhCN', '空气硬币', '再跟阿尔阿巴斯谈一谈。', '我对这里的居民口袋里的那些魔法小玩意儿很感兴趣，而且我愿意帮助你获得它们，$n。 \n\n可惜，我无法用这个世界的货币来报答你。我只能给你一种临时性的货币——由纯净的空气构成的硬币。但这总比啥都没有强！\n\n将我的灯带在身边。将你偷来的宝贝丢进来，我就会给你硬币。或许我这盏灯的前主人会用得着它们。', '', '', '', '', '', '', 25549),
(47604, 'zhCN', '魔法之地', '再……跟阿尔阿巴斯谈谈吧。', '我懂了。你那双小眼睛基本上就是个摆设，看不到那些精灵散布在这片土地各处的灌魔装饰品。他们一直都佩戴着珠宝，而你却看不见。 \n\n我提议我们合作，我的新朋友。我的灯目前正缺漂亮的装饰，实在是太过寒酸。我提议我们来做笔交易。由我来揭开这道阴险的面纱，而你则要把找到的宝物交给我。', '', '', '', '', '', '', 25549),
(47603, 'zhCN', '神秘而伟大的阿尔阿巴斯', '与阿尔阿巴斯谈一谈。', '我看见你了，渺小的凡人！感谢你照顾我的灯！', '', '', '', '', '', '', 25549),
(47595, 'zhCN', '我拿它们没用，但我还是要买', '为格里伏塔收集10000枚空气硬币。', '如果你想再多收集些，格里伏塔没有意见。话虽这么说，我现在没有以前那么需要这些东西了，所以我出的价钱也会降低点。', '为格里伏塔收集9999枚空气硬币。', '', '', '', '', '', 25549),
(47594, 'zhCN', '这些我要了，谢谢！', '为格里伏塔获取10000枚空气硬币。', '你说这些硬币会变成空气？听起来不错，我刚好知道该把它们给谁。', '', '', '', '', '', '', 25549),
(47592, 'zhCN', '钻石般闪亮', '从格里伏塔处购买一个权威认证有机灯具抛光工具包，用它给肮脏的灯具抛光。', '哦，抱歉。那个灯好像需要擦擦。我这正好有工具。', '', '', '', '', '', '', 25549),
(47591, 'zhCN', '想买灯吗？', '从格里伏塔处购买可疑的灯具。', '嘿，想买灯吗？你不会后悔的。', '', '', '', '', '', '', 25549),
(47589, 'zhCN', '正义之怒', '摧毁$1oa个军团灭绝者。', '灭绝者正在轰击我们，阻止我们前进。我只能保护我们不受爆炸的伤害。$B$B勇士，你必须突破他们的防线，消除那个保护灭绝者的屏障。$B$B如果你能摧毁维持护盾的锚，我就可以从远处净化他们。', '', '', '', '', '', '与毁灭之冠的先知维伦见面。', 25549),
(47566, 'zhCN', '加尔佐斯', '', '', '', '', '', '', '', '', 25549),
(47561, 'zhCN', '疱喉', '', '', '', '', '', '', '', '', 25549),
(47560, 'zhCN', '冰封时光碎片', '把冰封时光碎片带到龙眠神殿，解锁一个时光传送门。', '这块水晶碎片被包裹在一片薄薄的永冻冰层中。它还散发出巫妖那标志性的气味。', '', '', '', '', '', '', 25549),
(47559, 'zhCN', '微光时光碎片', '把微光时光碎片带到龙眠神殿，解锁一个时光传送门。', '这块水晶碎片闪烁着金属的光泽。根据克罗米的反应判断，它或许可以把你连接到另一个时间地点。', '', '', '', '', '', '', 25549),
(47558, 'zhCN', '魔触时光碎片', '把魔触时光碎片带到龙眠神殿，解锁一个时光传送门。', '这块水晶碎片上有绿色的邪恶能量留下的深深伤痕。被恐惧魔王拿在手里就是这个下场。', '', '', '', '', '', '', 25549),
(47557, 'zhCN', '阴燃时光碎片', '把阴燃时光碎片带到龙眠神殿，解锁一个时光传送门。', '这块水晶碎片摸起来很热。携带它的虚空生物身上并没有明显的使用火焰的痕迹，所以或许这块时光碎片与火焰存在其他的关联。', '', '', '', '', '', '', 25549),
(47554, 'zhCN', '拦截燃烧军团的计划', '搜索战场上的燃烧军团部队，消灭他们，夺取燃烧军团加密指令。找回圣光军团密码本，将命令解密。', '我们的斥候斯卡拉在信里写到，她得知了燃烧军团一个重大的计划。她当时正在追踪我们附近的燃烧军团的部队，找到了两个加密的命令，获得了详细信息。然后她就遇害了。燃烧军团把信息分成加密的几个部分，让我们无法读取。$b$b斯卡拉也写到了她的搭档，负责解密的布莱，在带着密码本想要回到我们阵地的时候也遇害了。我们需要那个密码本来翻译燃烧军团的命令。你一定要找到军团的命令和那本密码本，这至关重要！', '', '', '', '', '', '', 25549),
(47551, 'zhCN', '烈焰之痛', '', '', '', '', '', '', '', '', 25549),
(47550, 'zhCN', '时光巨龙的诸多优势', '第三次和克罗米对话，然后穿越未来，再次尝试拯救她。', '总之，不管是谁想弄死我，他的运气都挺差的。我可是造诣非凡的时光流大师！我们可以反复尝试，一次不够就多来几次，直到我不死了为止。\n\n我们还需要更多时间来阻止这次袭击。你觉得四个小时怎么样？', '', '', '', '', '', '', 25549),
(47545, 'zhCN', '回溯', '再次与克罗米交谈，前往未来，从其他龙眠大使处收集信息。', '现在我们知道攻击何时开始，以及攻击大致的方向。进展不错！我们只需要再获得一些详细情报，并且阻止这次攻击！\n\n如果你准备好再试一次，就告诉我吧。', '', '', '', '', '', '', 25549),
(47543, 'zhCN', '克罗米的死期', '与克罗米对话，然后穿越未来，查明她为什么会死。', '哦，$n！我正想到你呢！这就是所谓在对的时间来到对的地方吧！\n\n我刚在回顾时光流中的某些偏差，正巧发现了一些……意料之外的情况。一些令人不那么愉快的情况。\n\n我将在不久的将来死去。时运不济啊。\n\n我想穿越未来，查明我为什么会死，怎么死的，以及死在谁手里……但我觉得最好还是和你这样的$r一起去比较安心。你愿意和我一起吗？', '', '', '', '', '', '', 25549),
(47542, 'zhCN', '攻城大师沃兰', '', '', '', '', '', '', '', '', 25549),
(47541, 'zhCN', '最好的防御', '在破碎之野消灭$1oa个攻击者。', '如果是你把大主教带回来的，你就是受欢迎的盟友。$b$b还有很多人需要你。你看到那里破釜沉舟的士兵了吗？保护他们。杀掉敌人。$b$b对于牧师来说这些话可能太重了，但每杀死一个堕落者，架在我们脖子上的利剑就会减少一把。$b$b让他们看看，圣光会保护它的选民，也会把那些不信仰它的人烧成灰烬。$b$b结束后去找到伊米拉。她的部队人数更少，也更需要你的帮助。', '', '', '', '', '', '', 25549),
(47526, 'zhCN', '带回重型武器', '找到并获取圣光裁决者。', '圣光裁决者有安全机制，可以防止其落入到敌人的手上。我们可以触发它的召回机制，把它传送回船上。$b$b由于泽尼达尔没有运行，火炮应该会被召回到你的船上。你可以好好利用它的火力。$b$b但是这个过程会需要一段时间，而且可能会引起燃烧军团的注意。务必要小心。', '', '', '', '', '', '', 25549),
(47523, 'zhCN', '干扰检测：黑暗神殿', '重新经历进攻黑暗神殿的事件。', '$n，你总是这么准时。\n\n先说好消息吧，反正对我来说，不管什么消息都是同时发生的。多亏你在过去和未来发现的多个时空扭曲物体，我们终于弄清了如何检测新出现的时空扭曲。  \n\n坏消息是，我们之所以知道我们的技术管用，是因为黑暗神殿里发生了某种变化，它正在对整个时空造成巨大破坏！我们需要你去确保那次意义重大的突袭以和之前完全相同的结局收场，并且解决时空混乱的根源。', '', '', '', '', '', '', 25549),
(47508, 'zhCN', '自由射击', '进入光铸炮台并杀死$1oa个疯狂的灾翼蝠。', '小心点，满天都是蝙蝠的翅膀。我们必须尽量提供远程支援，但我们这里的事情也很多。$b$b看起来燃烧军团还没有摧毁全部的火炮。如果你能弄到一台，应该可以让那些空中的朋友好好感受下圣光。', '', '', '', '', '', '', 25549),
(47496, 'zhCN', '地堡炸弹', '', '', '', '', '', '', '', '', 25549),
(47473, 'zhCN', '估量对手', '与图拉扬谈一谈。', '图拉扬自然想听到点好消息，但我恐怕没有。如果我们现在朝燃烧军团的心脏进军，只会令我们灰飞烟灭。\n\n一定还有别的办法。我现在还没想到，但我知道我们一定可以找出来。\n\n别让图拉扬久等了。我们必须前进。', '', '', '', '', '', '', 25549),
(47456, 'zhCN', '摆脱虚空', '', '', '', '', '', '', '', '', 25549),
(47431, 'zhCN', '聚集圣光', '在克罗库营地与图拉扬见面。', '我和奥蕾莉亚希望能有更多的时间陪伴我们的儿子，但已经不能再等了，$n。我们必须现在就发动进攻。$b$b圣光军团只是分散了，并未被击败。所有幸存者都应该还在泽尼达尔附近。只要还有胜利的希望，我们就必须把他们召集起来并救回泽拉。$b$b消灭深渊领主后，前往泽尼达尔的道路应该就更安全了。你准备好后，就去克罗库营地和我汇合吧。', '', '', '', '', '', '', 25549),
(47430, 'zhCN', '监督枭兽', '观察附近跳舞、施放月火术和打瞌睡的枭兽宝宝，看你能学到什么。', '<玛考示意你观察该区域里的其他枭兽。>', '', '', '', '', '', '', 25549),
(47416, 'zhCN', '执政团之影', '返回维迪卡尔。', '塔尔加斯的话吐露了严峻的事实，我之前都不知道他掌握了这么重要的东西。为了能够最后再伤害我一次，他把答案告诉了我们。$b$b知识桂冠就藏在执政团之座，而且有重重守卫。$b$b如果我的怀疑是对的，那么我们面临的威胁可能超乎所有人的想象。$b$b一个黑暗纳鲁。$b$b我们回到维迪卡尔吧。我们要回去计划下一步的动作。', '', '', '', '', '', '', 25549),
(47330, 'zhCN', '惊恐世界的低语', '前往索拉查盆地与麦格尼见面，并听取警告。', '勇士，麦格尼需要你的帮助！$b$b那位代言人有话告诉你，也许这消息就来自艾泽拉斯自己。麦格尼似乎在理解她的意思的时候遇到了困难，但是我敢肯定，他可以把一切的来龙去脉好好地解释给你，至少比我要好。$b$b他说他在诺森德的索拉查盆地。他应该很快会和你联系。', '', '', '', '', '', '', 25549),
(47290, 'zhCN', '地下城世界事件 - 汉摩尔', '', '', '', '', '', '', '', '', 25549),
(47287, 'zhCN', '维迪卡尔矩阵核心', '将圣光裁决者链接到维迪卡尔矩阵核心。', '阿古斯上发生的很多事都让我担心不已，而泽拉的命运最让我忧心。有的时候我会想，我们做的事情是否正确？$b$b但我们必须坚持下去。我可以操纵给维迪卡尔提供能源的矩阵核心，你在这个星球上行动时，如果有需要，可以召唤我们火炮的力量。$b$b前往我们飞船中心舱室的矩阵核心。链接成功后，不管是现在还是将来，只要是给核心提供能量的东西，都可以为你所用。', '', '', '', '', '', '', 25549),
(47254, 'zhCN', '原汁原味', '击败诅咒之地的恶魔领主卡扎克、艾萨拉的艾索雷苟斯，以及翡翠梦境传送门里的梦魇之龙。', '很久以前，我们的大地笼罩在一片恐怖之中，即使最渺小的生命也必须挺身而出。\n\n我指的当然就是恶魔领主卡扎克、艾索雷苟斯和梦魇之龙。\n\n传说它们留下了巨额的宝藏，引来无数人通宵达旦地寻找。\n\n我们察觉到时光流中出现了扰乱，恰巧位于这些巨物曾经徘徊过的地方。\n\n你是否愿意为我们调查一下？每年这个时候都会发生奇怪的事情。', '', '', '', '', '', '', 25549),
(47253, 'zhCN', '原汁原味', '击败诅咒之地的卡扎克、艾萨拉的艾索雷苟斯，以及某一座翡翠梦境传送门附近的梦魇之龙。', '很久以前，巨大的恐怖之物在我们的土地上横行，即使是最弱小的人，也不得不进行英勇的抵抗。\n\n我指的当然就是卡扎克、艾索雷苟斯和梦魇之龙。\n\n传说，有很多人青睐他们的财宝，以至于会有狩猎大军在他们出没之地连夜驻扎。\n\n我们察觉到时光之路中出现了扰乱，恰巧位于这些巨大的怪物曾经出没的地方。\n\n你是否愿意为我们调查一下？每年这个时候都会发生奇怪的事情。', '', '', '', '', '', '', 25549),
(47252, 'zhCN', '有趣的时代', '在暴风城的皇家图书馆与历史学家勒洛尔见面。', '$n，我不想小题大做，但我们可能遇到了某种……时空干扰。\n\n你有没有听说过“希望你不会往事缠身”这句话？\n\n来暴风城的皇家图书馆找我，我们详细谈谈。', '', '', '', '', '', '', 25549),
(47251, 'zhCN', '有趣的时代', '在奥格瑞玛的精神谷与历史学家吉帕见面。', '$n，我不想小题大做，但我们可能遇到了某种……时空干扰。\n\n你有没有听说过“希望你不会往事缠身”这句话？\n\n来精神谷找我，我们详细谈谈。', '', '', '', '', '', '', 25549),
(47238, 'zhCN', '执政团之座', '找到知识桂冠。', '即使已经有了启迪印记，在得到完整的执政团之冠之前，它还是拯救不了我们。$b$b所以，即使明知鲁拉在那里等着我们，我们也必须进入执政团之座。$b$b这次任务非常艰险，但如果不是势在必行，我是不会开口的。$b$b我们会一起下去。来吧。', '', '', '', '', '', '', 25549),
(47224, 'zhCN', '维迪卡尔', '登上维迪卡尔。', '我们突袭的准备都已经就绪。只需要建立道标，然后把我们传送到船上。\n\n等道标到来后，把你的手放在道标的表面，然后登上复仇的工具维迪卡尔。', '', '', '', '', '', '在维迪卡尔与先知维伦见面。', 25549),
(47223, 'zhCN', '圣光逃亡', '在埃索达的圣光穹顶与先知维伦见面。', '先知维伦和其他人已经齐聚在下面的圣光穹顶。这条路的前方有个入口。\n\n我们必须马上找到先知，不要拖延进攻的时间。', '', '', '', '', '', '与圣光穹顶的先知维伦见面。', 25549),
(47222, 'zhCN', '海上潜行', '与温蕾萨·风行者谈谈以启航前往埃索达。', '萨格拉斯之墓只是个开始。如果不彻底摧毁燃烧军团，他们依然会回来，而且会更强大。\n\n我们要从海上前往秘蓝岛，避免引起不必要的注意。我们的进攻留给燃烧军团反应的时间越短越好。\n\n准备好出发后就下令吧。', '', '', '', '', '', '', 25549),
(47221, 'zhCN', '命运之手', '到暴风城港口和前往埃索达的护卫汇合。', '"$p,\n\n我们已经赢得许多对抗燃烧军团的战斗，但这一次我们要彻底终结这场战争。\n\n最后的准备工作已经就绪，准备向阿古斯出发。\n\n快点赶去暴风城港口。那里有艘船正在等着你，将会把你和你的盟友带往秘蓝岛。"', '', '', '', '', '', '', 25549),
(47220, 'zhCN', '黑暗中的道标', '把纳拉索斯残骸交给维迪卡尔的维伦。', '真是场…有趣的经历。$b$b<奥蕾莉亚摸了摸额头。>$b$b啊，我很难集中注意力。我需要你回到维伦那里，把这个交给他。$b$b<她把一件又冷又稠的东西放到你的手上。>$b$b我感觉仿佛应该交给他，但是我也不知道为什么。$b$b把我们知道的都告诉他。我相信罗姆尔一直关注着我们的进展。如果足够走运的话，一个道标应该朝我们这里来了。', '', '', '', '', '', '', 25549),
(47219, 'zhCN', '准备就绪', '消灭纳拉索斯并拿到他的心脏。', '经过一番深思熟虑，我决定再给奥蕾莉亚一次追求她自身命运的机会。$b$b我猜你很想知道那是什么意思，凡人。$b$b<双界行者大笑。>$b$b在前面的影卫营地的深处和我们汇合吧，我的弟兄们正在准备进行召唤，这次召唤可以为风行者提供足够的能量重新开始。$b$b你可以见证一下，驾驭虚空的能量时会出现什么情况。', '', '纳拉索斯虽然只是个半神，但他的气息依然萦绕在玛凯雷的黑暗角落。', '纳拉索斯', '', '', '', 25549),
(47218, 'zhCN', '影卫入侵', '杀死15个影卫虚灵。', '你现在肯定也知道了，我有些人民已经屈从于虚空的召唤，十分悲惨。$b$b我曾经想找到更多拥有足够意志力的人，却失望地发现这种人是如此稀少。$b$b对此我也无能为力。要想促成你我的目标，就必须消灭这些意志薄弱的生物。', '', '', '', '', '', '', 25549),
(47217, 'zhCN', '黑暗之源', '关闭5个虚空收割器。', '我想我知道他要说的事了，$n。$b$b我感到前方正在累积能量湍流。他们一定是在培养虚空，并且把虚空召唤到这里。$b$b不能让他们使整个城市陷入暗影。找到源头，不惜一切手段将其切断。$b$b我和双界行者还有一些事情要处理。', '', '', '', '', '', '', 25549),
(47203, 'zhCN', '虚空投影', '与奥蕾莉亚·风行者和双界行者一起调查幽影谷。', '那是双界行者。我对虚空的所有知识都是他教给我的，而且他还有更多东西可以教给我。$b$b如果他在这里，那么虚灵的据点对我来说就更有意思了。我本以为他是独一无二的，但如今我却看到了另一个与虚空有纠葛的家伙……$b$b来吧，我们如果想了解他知道的东西，就必须陪他玩这场游戏。他好像到北面的幽影谷去了。', '', '', '', '', '', '', 25549),
(47202, 'zhCN', '私人信息', '与先知维伦谈一谈。', '是时候了，我应该前往破碎海滩，亲眼看看我父亲牺牲的地方。\n\n如果我要成为我父亲那样伟大的国王……暴风城需要的国王，我必须亲眼见证我的人民所面临的威胁。\n\n请转告我的顾问，我去破碎海滩了。如果我自己去说的话，他们只会阻拦我。\n\n我会在救赎岗哨等你。再会。', '', '', '', '', '', '与先知维伦谈一谈。', 25549),
(47184, 'zhCN', '阿坎恩的危机', '进入虚空裂缝并解决阿坎恩。', '不管他的名字是什么，都肯定没有好意。我们必须追上他。$b$b我们进入传送门之前，$n……确保你已经做好了战斗的准备。虚空的影响一般都很狂暴。', '', '', '', '', '', '', 25549),
(47183, 'zhCN', '阿坎恩的计划', '跟随阿坎恩前往埃索隆。', '阿坎恩记得。他记得一些事情……这些东西……能够拯救我们。$b$b跟随阿坎恩。埃索隆在召唤！我们会向圣光祈祷。圣光会驱逐黑暗。$b$b<阿坎恩紧张地看着奥蕾莉亚。>$b$b阿坎恩会盯紧那一个的。', '', '', '', '', '', '', 25549),
(47182, 'zhCN', '姗姗来迟', '为维迪卡尔的火炮标记出阿古斯心泉，消灭燃烧军团的要塞，并且从大审判官拉尔加身上取回邪能之心。', '我了解到了很多信息。大审判官拉尔加去了山中燃烧军团堡垒附近的一个基地。他将阿古斯的邪能之心藏在那里，那正是他不朽生命的来源，由直接通往阿古斯核心的心泉提供能量。$b$b他正在准备发起攻击，所以你必须先发制人。标记出心泉的位置，我会用维迪卡尔的火炮对其发射神圣火焰。只要破坏了与阿古斯的邪能联系，就可以杀死拉尔加，拿到邪能之心。', '', '', '', '', '', '', 25549),
(47180, 'zhCN', '搏动的疯狂', '驱散5个虚空具象。', '尽管并非完全清醒，但这名破碎者仍然保留了一些理智。$b$b我能感觉到附近存在虚空的力量，但仅限于小范围的几处。驱散这些虚空具象应该能够帮助我们的朋友澄清思绪。$b$b也许我们可以利用你发现的祈祷者碎片，因为它们依然蕴含少量的光明能量。$b$b与此同时，我会尽量试着去理解他的自言自语。也许我们可以了解到这里究竟发生了什么。', '', '', '', '', '', '', 25549),
(47148, 'zhCN', '与众不同', '赢得1场PvP乱斗。', '即使是最嗜血的争斗者，最终也会变得疲惫，逐渐远离永无休止的战争。他们想寻找一种新的方式来考验他们的勇气，并摧毁他们的敌人。\n\n加入正在进行的乱斗，与你的敌人决一死战吧。这个活动抛弃了传统的规则，只在限定时间内才能参加。', '', '', '', '', '', '', 25549),
(47139, 'zhCN', '森提纳克斯号印记', '收集$1oa个森提纳克斯号印记。', '森提纳克斯号在破碎海滩上散播恐惧，释放出了成群的恶魔，对我们的军队造成了很大威胁。这些敌人试图阻止我们攻下古墓。\n\n他们必将失败。\n\n把这支邪恶部队中最强大的恶魔引出来，然后把他们解决掉，并收集他们身上的印记。让军团在我们的力量面前颤抖吧！', '', '', '', '', '', '', 25549),
(47137, 'zhCN', '抗魔联军勇士', '回到你的职业大厅并招募一名新的勇士。', '收复破碎海滩的战斗正在快速消耗我们的资源。但我们不能放弃，否则就等于是把我们努力获得的战果拱手让给燃烧军团。\n\n你的组织成员已经付出了许多，但这还不够。\n\n请集结你的勇士，并尽力扩充部队。这片土地上或许还存在我们没有利用到的力量，而这些力量可以让战局倒向我们这边。', '', '', '', '', '', '', 25549),
(47134, 'zhCN', '挫败军团越狱', '在军团释放大审判官拉尔加之前找到他。', '大审判官拉尔加和阿古斯本地的邪能间存在某种联系，这让他无法被杀死。很久以前，纳鲁把他关押在禁魔监狱。$b$b当凯尔萨斯·逐日者攻击这座要塞时，我们被迫乘坐埃索达逃离。$b$b而在燃烧军团上一次入侵艾泽拉斯期间，部分军团囚犯逃离了禁魔监狱，但拉尔加却没有。不要让他得到释放，我会研究并破解他的不死的奥秘。$b$b我能帮助你接近他，剩下的就靠你了。', '', '', '', '', '', '', 25549),
(47129, 'zhCN', '欺诈者', '击败萨格拉斯之墓的基尔加丹。', '这种印记只有欺诈者基尔加丹最强大的仆从才会携带，它意味着基尔加丹的出现。一定要击败他。', '', '', '', '', '', '', 25549),
(47128, 'zhCN', '欺诈者', '击败萨格拉斯之墓的基尔加丹。', '这种印记只有欺诈者基尔加丹最强大的仆从才会携带，它意味着基尔加丹的出现。一定要击败他。', '', '', '', '', '', '', 25549),
(47127, 'zhCN', '欺诈者', '击败萨格拉斯之墓的基尔加丹。', '这种印记只有欺诈者基尔加丹最强大的仆从才会携带，它意味着基尔加丹的出现。一定要击败他。', '', '', '', '', '', '', 25549),
(47126, 'zhCN', '欺诈者', '击败萨格拉斯之墓的基尔加丹。', '这种印记只有欺诈者基尔加丹最强大的仆从才会携带，它意味着基尔加丹的出现。一定要击败他。', '', '', '', '', '', '', 25549),
(47125, 'zhCN', '堕落的化身', '击败萨格拉斯之墓的堕落的化身。', '我们决战的障碍只剩下堕落的化身了。消灭他，了结此事。', '', '', '', '', '', '', 25549),
(47124, 'zhCN', '堕落的化身', '击败萨格拉斯之墓的堕落的化身。', '我们决战的障碍只剩下堕落的化身了。消灭他，了结此事。', '', '', '', '', '', '', 25549),
(47123, 'zhCN', '堕落的化身', '击败萨格拉斯之墓的堕落的化身。', '我们决战的障碍只剩下堕落的化身了。消灭他，了结此事。', '', '', '', '', '', '', 25549),
(47122, 'zhCN', '堕落的化身', '击败萨格拉斯之墓的堕落的化身。', '我们决战的障碍只剩下堕落的化身了。消灭他，了结此事。', '', '', '', '', '', '', 25549),
(47121, 'zhCN', '解放灵魂', '击败萨格拉斯之墓的绝望的聚合体。', '墓穴中的灵魂被一个可怕的引擎所扭曲。毁掉它，让灵魂从折磨中获得解脱。', '', '', '', '', '', '', 25549),
(47120, 'zhCN', '解放灵魂', '击败萨格拉斯之墓的绝望的聚合体。', '墓穴中的灵魂被一个可怕的引擎所扭曲。毁掉它，让灵魂从折磨中获得解脱。', '', '', '', '', '', '', 25549),
(47119, 'zhCN', '解放灵魂', '击败萨格拉斯之墓的绝望的聚合体。', '墓穴中的灵魂被一个可怕的引擎所扭曲。毁掉它，让灵魂从折磨中获得解脱。', '', '', '', '', '', '', 25549),
(47118, 'zhCN', '解放灵魂', '击败萨格拉斯之墓的绝望的聚合体。', '墓穴中的灵魂被一个可怕的引擎所扭曲。毁掉它，让灵魂从折磨中获得解脱。', '', '', '', '', '', '', 25549),
(47117, 'zhCN', '古墓主母', '消灭萨格拉斯之墓的主母萨丝琳。', '纳迦主母正在污染墓穴下的海洋住民，消灭她。', '', '', '', '', '', '', 25549),
(47116, 'zhCN', '古墓主母', '消灭萨格拉斯之墓的主母萨丝琳。', '纳迦主母正在污染墓穴下的海洋住民，消灭她。', '', '', '', '', '', '', 25549),
(47115, 'zhCN', '古墓主母', '消灭萨格拉斯之墓的主母萨丝琳。', '纳迦主母正在污染墓穴下的海洋住民，消灭她。', '', '', '', '', '', '', 25549),
(47114, 'zhCN', '古墓主母', '消灭萨格拉斯之墓的主母萨丝琳。', '纳迦主母正在污染墓穴下的海洋住民，消灭她。', '', '', '', '', '', '', 25549),
(47112, 'zhCN', '迷失之魂', '释放$1oa个迷失之魂。', '我这辈子都没有见过这样严重的破坏……这样悲惨的景象。连我们脚下的土地，也是用盟友的牺牲铺筑的。\n\n即使是现在，我也能够看到联盟士兵们迷失的灵魂徘徊在废墟之间。\n\n在让我们勇敢的士兵的灵魂得到安息之前，我不能离开这里。我们欠他们……我自己欠他们太多了。', '', '', '', '', '', '', 25549),
(47104, 'zhCN', '被囚禁的大审判官', '前往维迪卡尔，向技师罗姆尔询问大审判官拉尔加的信息。', '该报告指出军团正试图释放一名被囚禁的军团审判官。他名为拉尔加，是阿古斯本地的一只恶魔。因为拥有一种独特的神秘魔法，他无法被杀死。$b$b于是他被关押在风暴要塞的禁魔监狱里。$b$b圣光之母告诉我们这座纳鲁要塞的存在，但我从未亲眼目睹它，$n。图拉扬提到维迪卡尔和风暴要塞存在某种联系。也许你飞船上的工程师能懂得更多。', '', '', '', '', '', '', 25549),
(47102, 'zhCN', '神秘的信件', '在泽尼达尔周围寻找知悉密封的信件的人。', '<你在遗体上找到了一封装饰着圣光骑士团印章的信件。$b$b既然有人杀死信使阻止邮件的递送，它的内容一定很重要。>', '', '', '', '', '', '', 25549),
(47101, 'zhCN', '阿坎恩的祈祷', '收集5个祈祷者碎片。', '<当你靠近雕像，一个阴沉的声音在你的脑海中响起。>$b$b“你必须抵抗暗影的拉拢，来找我吧，兄弟们姐妹们，团结在圣光之下。$b$b让阿坎恩指引你们回家。”$b$b<剩余的讯息已经错乱不清，而附近的破碎者们似乎在用牙啃着雕像的碎片。>', '', '', '', '', '', '', 25549),
(47100, 'zhCN', '阿坎恩的痛苦', '在奥罗纳尔陷坑杀死12名破碎者。', '黑暗包围着我们……圣光已经离开此地……$b$b<阿坎恩自言自语道，接着才注意到你在和他说话。>$b$b阿坎恩没能拯救他们，兄弟们，姐妹们，低语扭曲了他们，圣光看不到他们，它抛弃了我们。$b$b阿坎恩失败了。$b$b<阿坎恩出神地望着空气。>', '', '', '', '', '', '', 25549),
(47097, 'zhCN', '漫步回忆', '护送安度因国王前往破碎海滩的幽灵废墟。', '很高兴有你陪在我身边，$n。\n\n我来到破碎海滩，是想亲眼见证我的父亲……见证联盟为了保护我们的世界而付出的代价。\n\n如果我对我的人民遭受的痛苦和付出的牺牲熟视无睹，那我就永远无法领导人民走向和平。\n\n时间不早了，我们要继续前进。', '', '', '', '', '', '', 25549),
(47079, 'zhCN', '递送失落的知识', '与你的职业大厅的神器研究者谈一谈。', '这本古代暗夜精灵之书生来就是为了寻求知识。它可以成为你研究神器的利器。\n\n我敢打赌，你职业大厅里的学者会发现它的巨大价值，甚至能解锁新的强化途径。\n\n我建议你马上把书带给他们。为了击败燃烧军团，我们需要利用一切可以利用的条件！', '', '', '', '', '', '', 25549),
(47077, 'zhCN', '递送失落的知识', '与你的职业大厅的神器研究者谈一谈。', '这本古代暗夜精灵之书生来就是为了寻求知识。它可以成为你研究神器的利器。\n\n我敢打赌，你职业大厅里的学者会发现它的巨大价值，甚至能解锁新的强化途径。\n\n我建议你马上把书带给他们。为了击败燃烧军团，我们需要利用一切可以利用的条件！', '', '', '', '', '', '', 25549),
(47076, 'zhCN', '递送失落的知识', '与你的职业大厅的神器研究者谈一谈。', '这本古代暗夜精灵之书生来就是为了寻求知识。它可以成为你研究神器的利器。\n\n我敢打赌，你职业大厅里的学者会发现它的巨大价值，甚至能解锁新的强化途径。\n\n我建议你马上把书带给他们。为了击败燃烧军团，我们需要利用一切可以利用的条件！', '', '', '', '', '', '', 25549),
(47072, 'zhCN', '递送失落的知识', '与你的职业大厅的神器研究者谈一谈。', '这本古代暗夜精灵之书生来就是为了寻求知识。它可以成为你研究神器的利器。\n\n我敢打赌，你职业大厅里的学者会发现它的巨大价值，甚至能解锁新的强化途径。\n\n我建议你马上把书带给他们。为了击败燃烧军团，我们需要利用一切可以利用的条件！', '', '', '', '', '', '', 25549),
(47071, 'zhCN', '递送失落的知识', '与你的职业大厅的神器研究者谈一谈。', '这本古代暗夜精灵之书生来就是为了寻求知识。它可以成为你研究神器的利器。\n\n我敢打赌，你职业大厅里的学者会发现它的巨大价值，甚至能解锁新的强化途径。\n\n我建议你马上把书带给他们。为了击败燃烧军团，我们需要利用一切可以利用的条件！', '', '', '', '', '', '', 25549),
(47070, 'zhCN', '递送失落的知识', '与你的职业大厅的神器研究者谈一谈。', '这本古代暗夜精灵之书生来就是为了寻求知识。它可以成为你研究神器的利器。\n\n我敢打赌，你职业大厅里的学者会发现它的巨大价值，甚至能解锁新的强化途径。\n\n我建议你马上把书带给他们。为了击败燃烧军团，我们需要利用一切可以利用的条件！', '', '', '', '', '', '', 25549),
(47067, 'zhCN', '寻找失落的知识', '在破碎海滩的几处暗夜精灵废墟里使用这本书。', '我们的部队在这次的突袭中发现了一本古代暗夜精灵之书。这本书居然能在这样严酷的环境下保存这么久，这真是出人意料。\n\n书上的魔力因为年代久远已经有些消散了。但是我感觉到这本书有点……饥饿，仿佛想要到暗夜精灵许多年以前练习魔法的地方去。\n\n把这本书带到附近的各个废墟，或许就能揭示某些秘密。在对抗军团的时候，我们可以利用这些秘密抢占先机。\n\n', '', '', '', '', '', '', 25549),
(47066, 'zhCN', '圣洁之地', '修复执政团之末下方的阿古尼特矩阵。', '我们已经有了所需的一切。$b$b在下方的壁龛可以找到破碎的阿古尼特矩阵。换上钥石后可以将其完全修复。$b$b然后，你启动的晶塔就可以击退那些仍在猎杀我人民的敌人。这场战斗终将结束。$b$b我希望他们能从中获得一丝安宁。', '', '', '', '', '', '', 25549),
(47061, 'zhCN', '阿波克隆', '', '', '', '', '', '', '', '', 25549),
(47059, 'zhCN', '野性德鲁伊：莱维娅·劳伦斯的窘境', '在城里打听莱维娅·劳伦斯的情报。', '莱维娅·劳伦斯曾是肯瑞托的成员。由于涉足暗影魔法，她被赶出了达拉然。但她对这里的街道太熟悉了，我们不可能长期阻止她进入这座城市。\n\n莱维娅失踪了，我对此极为关注。她的研究可能已经引起了燃烧军团的注意。这种事以前也发生过。如果她的知识落入了燃烧军团的手中，情况就会很危险。\n\n她最后一次出现是在铭文师的殿堂。去那里打听一下，看看能不能找到她的去向。\n\n|cFF660000专精：野性德鲁伊|r', '', '', '', '', '', '', 25549),
